"use client"

import { useState, useTransition, useRef, useEffect, useCallback, useMemo } from "react"
import type { AppUser, Gallery, Tag, SessionUser } from "@/lib/types"
import type { AnnouncementBanner, AnnouncementNote } from "@/lib/db"
import {
  adminBanUser,
  adminUnbanUser,
  adminForceRoleSync,
  adminCreateGallery,
  adminUpdateGallery,
  adminDeleteGallery,
  adminBulkToggleGalleries,
  adminBulkDeleteGalleries,
  adminAddLink,
  adminUpdateLink,
  adminDeleteLink,
  adminCreateTag,
  adminUpdateTag,
  adminDeleteTag,
  adminSetAnnouncement,
  adminCreateBackup,
  adminResetStats,
  adminSaveNote,
} from "@/app/admin/actions"
import { NoteEditor } from "@/components/admin/note-editor"

// ─── Types ────────────────────────────────────────────────────────────────────
interface Stats {
  totalUsers: number
  bannedUsers: number
  totalGalleries: number
  activeGalleries: number
  totalLinks: number
  totalViews: number
  totalCopies: number
  totalTags: number
  activeTags: number
}

interface Props {
  session: SessionUser
  users: AppUser[]
  galleries: Gallery[]
  tags: Tag[]
  stats: Stats
  announcement: AnnouncementBanner | null
  note: AnnouncementNote | null
}

type Tab = "overview" | "galleries" | "users" | "tags" | "announcement" | "note" | "backup"
type SortField = "title" | "views" | "copies" | "rate" | "links" | "created"
type SortDir = "asc" | "desc"

const ROLES = ["69Bath", "99Bath", "199Bath", "299Bath", "699Bath"] as const
const ROLE_LEVELS: Record<string, number> = {
  "69Bath": 1, "99Bath": 2, "199Bath": 3, "299Bath": 4, "699Bath": 5,
}
const ROLE_COLORS: Record<string, string> = {
  "69Bath": "#6b7280", "99Bath": "#3b82f6", "199Bath": "#8b5cf6", "299Bath": "#f59e0b", "699Bath": "#ef4444",
}

// ─── Helpers ──────────────────────────────────────────────────────────────────
function RoleBadge({ role }: { role: string }) {
  return (
    <span
      style={{ backgroundColor: ROLE_COLORS[role] + "22", color: ROLE_COLORS[role], borderColor: ROLE_COLORS[role] + "44" }}
      className="text-[10px] font-bold px-1.5 py-0.5 rounded border whitespace-nowrap"
    >
      {role}
    </span>
  )
}

function StatCard({ label, value, sub, accent }: { label: string; value: number | string; sub?: string; accent?: string }) {
  return (
    <div className="bg-[#111118] border border-[#1e1e2e] rounded-xl p-4 hover:border-[#2a2a3e] transition-colors">
      <div className="text-[#4a4a6a] text-xs font-medium uppercase tracking-widest mb-1">{label}</div>
      <div className={`text-3xl font-black ${accent ?? "text-white"}`}>
        {typeof value === "number" ? value.toLocaleString() : value}
      </div>
      {sub && <div className="text-[#4a4a6a] text-xs mt-1">{sub}</div>}
    </div>
  )
}

function TabBtn({ active, onClick, icon, children, badge }: { active: boolean; onClick: () => void; icon?: string; children: React.ReactNode; badge?: React.ReactNode }) {
  return (
    <button
      onClick={onClick}
      className={`flex items-center gap-1.5 px-4 py-2 text-sm font-semibold rounded-lg transition-all whitespace-nowrap ${
        active ? "bg-[#2563eb] text-white shadow-lg shadow-blue-500/20" : "text-[#6b6b8a] hover:text-white hover:bg-[#1e1e2e]"
      }`}
    >
      {icon && <span className="text-base leading-none">{icon}</span>}
      {children}
      {badge}
    </button>
  )
}

// ─── Confirm Dialog ────────────────────────────────────────────────────────────
interface ConfirmDialogProps {
  title: string
  message: string
  confirmLabel?: string
  cancelLabel?: string
  danger?: boolean
  onConfirm: () => void
  onCancel: () => void
  withInput?: { label: string; placeholder: string; onValue: (v: string) => void }
}

function ConfirmDialog({ title, message, confirmLabel = "Confirm", cancelLabel = "Cancel", danger, onConfirm, onCancel, withInput }: ConfirmDialogProps) {
  const [inputValue, setInputValue] = useState("")
  useEffect(() => {
    const handler = (e: KeyboardEvent) => { if (e.key === "Escape") onCancel() }
    window.addEventListener("keydown", handler)
    return () => window.removeEventListener("keydown", handler)
  }, [onCancel])
  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm" onClick={onCancel}>
      <div className="bg-[#111118] border border-[#2a2a3e] rounded-2xl w-full max-w-sm shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <div className="p-6 space-y-3">
          <div className="text-base font-bold text-white">{title}</div>
          <div className="text-sm text-[#8b8baa]">{message}</div>
          {withInput && (
            <div className="mt-3">
              <label className="text-xs text-[#4a4a6a] block mb-1">{withInput.label}</label>
              <input
                autoFocus
                value={inputValue}
                onChange={(e) => { setInputValue(e.target.value); withInput.onValue(e.target.value) }}
                placeholder={withInput.placeholder}
                className="w-full bg-[#0d0d15] border border-[#1e1e2e] rounded-xl px-4 py-2.5 text-sm text-white focus:border-blue-500 outline-none"
              />
            </div>
          )}
        </div>
        <div className="flex gap-3 px-6 pb-6">
          <button onClick={onCancel} className="flex-1 px-4 py-2 text-sm text-[#6b6b8a] hover:text-white border border-[#1e1e2e] hover:border-[#2a2a3e] rounded-xl transition-colors">
            {cancelLabel}
          </button>
          <button
            onClick={onConfirm}
            disabled={withInput !== undefined && inputValue.trim() === ""}
            className={`flex-1 px-4 py-2 text-sm font-semibold rounded-xl transition-colors disabled:opacity-40 ${
              danger ? "bg-red-600 hover:bg-red-700 text-white" : "bg-blue-600 hover:bg-blue-700 text-white"
            }`}
          >
            {confirmLabel}
          </button>
        </div>
      </div>
    </div>
  )
}

// ─── Main Component ───────────────────────────────────────────────────────────
export function AdminShell({ session, users, galleries, tags, stats, announcement, note }: Props) {
  const [tab, setTab] = useState<Tab>("overview")
  const [isPending, startTransition] = useTransition()
  const [toast, setToast] = useState<{ msg: string; type: "ok" | "err" } | null>(null)

  function notify(msg: string, type: "ok" | "err" = "ok") {
    setToast({ msg, type })
    setTimeout(() => setToast(null), 3500)
  }

  function run(fn: () => Promise<{ ok: boolean }>, successMsg: string) {
    startTransition(async () => {
      try {
        await fn()
        notify(successMsg)
      } catch (e) {
        notify((e as Error).message, "err")
      }
    })
  }

  const conversionRate = stats.totalViews > 0 ? ((stats.totalCopies / stats.totalViews) * 100).toFixed(1) : "0.0"

  return (
    <div className="min-h-screen bg-[#0a0a0f] text-white font-sans">
      {/* Header */}
      <div className="border-b border-[#1e1e2e] bg-[#0d0d15] sticky top-0 z-40">
        <div className="max-w-7xl mx-auto px-6 py-3 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-blue-500 to-violet-600 flex items-center justify-center text-xs font-black shrink-0">A</div>
            <div>
              <div className="text-sm font-bold text-white leading-none">Solara Admin</div>
              <div className="text-[10px] text-[#4a4a6a] mt-0.5">Backend Control Panel</div>
            </div>
          </div>
          <div className="flex items-center gap-3">
            {isPending && (
              <div className="flex items-center gap-2 text-xs text-[#4a4a6a]">
                <div className="w-3.5 h-3.5 border-2 border-blue-500 border-t-transparent rounded-full animate-spin" />
                <span>Saving…</span>
              </div>
            )}
            <a href="/" className="text-xs text-[#4a4a6a] hover:text-white transition-colors px-2 py-1 rounded hover:bg-[#1e1e2e]">← View site</a>
            <div className="flex items-center gap-2 pl-2 border-l border-[#1e1e2e]">
              <img src={session.avatar ?? "/placeholder-user.jpg"} className="w-7 h-7 rounded-full border-2 border-[#1e1e2e]" alt="" />
              <span className="text-xs text-[#6b6b8a] hidden sm:block">{session.discord_tag}</span>
            </div>
          </div>
        </div>
        {/* Tabs */}
        <div className="max-w-7xl mx-auto px-6 pb-3 flex gap-1 overflow-x-auto scrollbar-none">
          <TabBtn active={tab === "overview"} onClick={() => setTab("overview")} icon="📊">Overview</TabBtn>
          <TabBtn active={tab === "galleries"} onClick={() => setTab("galleries")} icon="🖼" badge={stats.totalGalleries > 0 ? <span className="ml-1 bg-[#1e1e2e] text-[#6b6b8a] text-[10px] px-1.5 py-0.5 rounded-full">{stats.totalGalleries}</span> : null}>Galleries</TabBtn>
          <TabBtn active={tab === "users"} onClick={() => setTab("users")} icon="👥" badge={stats.bannedUsers > 0 ? <span className="ml-1 bg-red-900/50 text-red-400 text-[10px] px-1.5 py-0.5 rounded-full">{stats.bannedUsers} banned</span> : null}>Users</TabBtn>
          <TabBtn active={tab === "tags"} onClick={() => setTab("tags")} icon="🏷">Tags</TabBtn>
          <TabBtn active={tab === "announcement"} onClick={() => setTab("announcement")} icon="📢" badge={announcement ? <span className="ml-1 w-1.5 h-1.5 rounded-full bg-yellow-400 inline-block" /> : null}>Announcement</TabBtn>
          <TabBtn active={tab === "note"} onClick={() => setTab("note")} icon="📝" badge={note ? <span className="ml-1 w-1.5 h-1.5 rounded-full bg-emerald-400 inline-block" /> : null}>Note</TabBtn>
          <TabBtn active={tab === "backup"} onClick={() => setTab("backup")} icon="💾">Backup</TabBtn>
        </div>
      </div>

      {/* Toast */}
      {toast && (
        <div className={`fixed top-4 right-4 z-50 px-4 py-3 rounded-xl text-sm font-semibold shadow-xl border transition-all ${
          toast.type === "ok" ? "bg-[#0d2e1a] border-green-700 text-green-400" : "bg-[#2e0d0d] border-red-700 text-red-400"
        }`}>
          {toast.type === "ok" ? "✓" : "✗"} {toast.msg}
        </div>
      )}

      <div className="max-w-7xl mx-auto px-6 py-8">
        {tab === "overview" && <OverviewTab stats={stats} galleries={galleries} users={users} conversionRate={conversionRate} />}
        {tab === "galleries" && <GalleriesTab galleries={galleries} tags={tags} run={run} notify={notify} />}
        {tab === "users" && <UsersTab users={users} run={run} notify={notify} />}
        {tab === "tags" && <TagsTab tags={tags} run={run} notify={notify} session={session} />}
        {tab === "announcement" && <AnnouncementTab current={announcement} run={run} />}
        {tab === "note" && <NoteEditor initialNote={note} />}
        {tab === "backup" && <BackupTab notify={notify} galleries={galleries} run={run} />}
      </div>
    </div>
  )
}

// ─── Overview Tab ─────────────────────────────────────────────────────────────
function OverviewTab({ stats, galleries, users, conversionRate }: { stats: Stats; galleries: Gallery[]; users: AppUser[]; conversionRate: string }) {
  const topGalleries = [...galleries].sort((a, b) => b.stats.total_views - a.stats.total_views).slice(0, 5)
  const recentUsers = [...users].sort((a, b) => new Date(b.last_login).getTime() - new Date(a.last_login).getTime()).slice(0, 5)
  const allAudit = users
    .flatMap((u) => u.audit_log.map((e) => ({ ...e, user: u })))
    .sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
    .slice(0, 12)

  return (
    <div className="space-y-8">
      <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-4">
        <StatCard label="Total Users" value={stats.totalUsers} sub={`${stats.bannedUsers} banned`} />
        <StatCard label="Galleries" value={stats.totalGalleries} sub={`${stats.activeGalleries} active`} />
        <StatCard label="Links" value={stats.totalLinks} sub={`across all galleries`} />
        <StatCard label="Total Views" value={stats.totalViews} />
        <StatCard label="Total Copies" value={stats.totalCopies} />
        <StatCard label="Conversion" value={`${conversionRate}%`} sub="copies / views" accent="text-emerald-400" />
      </div>

      <div className="grid md:grid-cols-3 gap-6">
        <div className="bg-[#111118] border border-[#1e1e2e] rounded-xl p-5">
          <div className="text-xs font-bold text-[#4a4a6a] uppercase tracking-widest mb-4">🏆 Top Galleries by Views</div>
          <div className="space-y-3">
            {topGalleries.map((g, i) => {
              const rate = g.stats.total_views > 0 ? Math.round((g.stats.total_copies / g.stats.total_views) * 100) : 0
              return (
                <div key={g.id} className="flex items-center gap-3">
                  <span className="text-xs text-[#4a4a6a] w-4 shrink-0">{i + 1}</span>
                  {g.thumbnail && (
                    <img src={g.thumbnail} alt="" className="w-8 h-8 rounded object-cover border border-[#1e1e2e] shrink-0"
                      onError={(e) => { e.currentTarget.style.opacity = "0.2" }} />
                  )}
                  <div className="flex-1 min-w-0">
                    <div className="text-sm font-semibold text-white truncate">{g.title}</div>
                    <div className="text-[10px] text-[#4a4a6a]">{rate}% copy rate</div>
                  </div>
                  <div className="text-right shrink-0">
                    <div className="text-sm font-bold text-blue-400">{g.stats.total_views.toLocaleString()}</div>
                    <div className="text-[10px] text-[#4a4a6a]">{g.stats.total_copies} copies</div>
                  </div>
                </div>
              )
            })}
            {topGalleries.length === 0 && <div className="text-xs text-[#4a4a6a]">No galleries yet</div>}
          </div>
        </div>

        <div className="bg-[#111118] border border-[#1e1e2e] rounded-xl p-5">
          <div className="text-xs font-bold text-[#4a4a6a] uppercase tracking-widest mb-4">🕐 Recent Logins</div>
          <div className="space-y-3">
            {recentUsers.map((u) => (
              <div key={u.user_id} className="flex items-center justify-between gap-3">
                <div className="flex items-center gap-2.5 min-w-0">
                  <img src={u.avatar ?? "/placeholder-user.jpg"} className="w-7 h-7 rounded-full border border-[#1e1e2e] shrink-0" alt="" />
                  <div className="min-w-0">
                    <div className="text-sm font-semibold text-white truncate">{u.discord_tag}</div>
                    <div className="flex gap-1 mt-0.5 flex-wrap">
                      {u.roles_cache.active_roles.slice(0, 2).map((r) => <RoleBadge key={r} role={r} />)}
                      {u.roles_cache.active_roles.length === 0 && <span className="text-[10px] text-[#4a4a6a]">No roles</span>}
                    </div>
                  </div>
                </div>
                <div className="text-[10px] text-[#4a4a6a] shrink-0 text-right">
                  {new Date(u.last_login).toLocaleDateString("th-TH")}
                </div>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-[#111118] border border-[#1e1e2e] rounded-xl p-5">
          <div className="text-xs font-bold text-[#4a4a6a] uppercase tracking-widest mb-4">⚡ Activity Feed</div>
          <div className="space-y-2 max-h-[280px] overflow-y-auto pr-1">
            {allAudit.length === 0 && <div className="text-xs text-[#4a4a6a]">No activity yet</div>}
            {allAudit.map((e, i) => {
              const isCopy = e.action === "copy_link"
              const isBan = e.action.startsWith("admin_ban") || e.action === "banned_by_admin"
              const isAdmin = e.action.startsWith("admin_")
              return (
                <div key={i} className="flex items-start gap-2">
                  <img src={e.user.avatar ?? "/placeholder-user.jpg"} className="w-5 h-5 rounded-full border border-[#1e1e2e] shrink-0 mt-0.5" alt="" />
                  <div className="min-w-0 flex-1">
                    <div className="flex items-center gap-1 flex-wrap">
                      <span className="text-[11px] font-semibold text-white truncate max-w-[80px]">{e.user.discord_tag.split("#")[0]}</span>
                      <span className={`text-[10px] px-1 py-0.5 rounded font-mono ${
                        isBan ? "bg-red-900/40 text-red-400" :
                        isAdmin ? "bg-violet-900/40 text-violet-400" :
                        isCopy ? "bg-blue-900/30 text-blue-400" :
                        "bg-[#1e1e2e] text-[#6b6b8a]"
                      }`}>{e.action}</span>
                    </div>
                    <div className="text-[9px] text-[#4a4a6a] mt-0.5">
                      {new Date(e.timestamp).toLocaleString("th-TH", { hour: "2-digit", minute: "2-digit", day: "2-digit", month: "2-digit" })}
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      </div>
    </div>
  )
}

// ─── Galleries Tab (OVERHAULED) ────────────────────────────────────────────────
function GalleriesTab({
  galleries, tags, run, notify,
}: {
  galleries: Gallery[]
  tags: Tag[]
  run: (fn: () => Promise<{ ok: boolean }>, msg: string) => void
  notify: (msg: string, type?: "ok" | "err") => void
}) {
  const [viewMode, setViewMode] = useState<"list" | "grid" | "table">("list")
  const [search, setSearch] = useState("")
  const [filterStatus, setFilterStatus] = useState<"all" | "active" | "inactive">("all")
  const [filterTag, setFilterTag] = useState<string>("all")
  const [filterRole, setFilterRole] = useState<string>("all")
  const [sortField, setSortField] = useState<SortField>("views")
  const [sortDir, setSortDir] = useState<SortDir>("desc")
  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [editingGallery, setEditingGallery] = useState<Gallery | null>(null)
  const [creatingGallery, setCreatingGallery] = useState(false)
  const [expandedLinks, setExpandedLinks] = useState<string | null>(null)
  const [deleteDialog, setDeleteDialog] = useState<Gallery | null>(null)
  const [editingLinkOf, setEditingLinkOf] = useState<Gallery | null>(null)
  const [bulkDeleteDialog, setBulkDeleteDialog] = useState(false)

  // ── Sort helper
  function toggleSort(field: SortField) {
    if (sortField === field) setSortDir(d => d === "asc" ? "desc" : "asc")
    else { setSortField(field); setSortDir("desc") }
  }

  const SortIcon = ({ field }: { field: SortField }) => {
    if (sortField !== field) return <span className="text-[#2a2a3e] ml-0.5">↕</span>
    return <span className="text-blue-400 ml-0.5">{sortDir === "asc" ? "↑" : "↓"}</span>
  }

  // ── Active tag names for filter pill dropdown
  const activeTags = tags.filter(t => t.is_active)

  // ── Filter + sort pipeline
  const filtered = useMemo(() => {
    let list = galleries.filter((g) => {
      const matchSearch = g.title.toLowerCase().includes(search.toLowerCase()) || g.id.includes(search.toLowerCase())
      const matchStatus = filterStatus === "all" || (filterStatus === "active" ? g.is_active : !g.is_active)
      const matchTag = filterTag === "all" || g.tags.includes(filterTag)
      const matchRole = filterRole === "all" || g.access.min_role_name === filterRole
      return matchSearch && matchStatus && matchTag && matchRole
    })
    list = [...list].sort((a, b) => {
      let va: number, vb: number
      switch (sortField) {
        case "title": return sortDir === "asc" ? a.title.localeCompare(b.title) : b.title.localeCompare(a.title)
        case "views": va = a.stats.total_views; vb = b.stats.total_views; break
        case "copies": va = a.stats.total_copies; vb = b.stats.total_copies; break
        case "rate":
          va = a.stats.total_views > 0 ? a.stats.total_copies / a.stats.total_views : 0
          vb = b.stats.total_views > 0 ? b.stats.total_copies / b.stats.total_views : 0
          break
        case "links": va = a.links.length; vb = b.links.length; break
        case "created":
          return sortDir === "asc"
            ? new Date(a.uploaded_at).getTime() - new Date(b.uploaded_at).getTime()
            : new Date(b.uploaded_at).getTime() - new Date(a.uploaded_at).getTime()
        default: va = 0; vb = 0
      }
      return sortDir === "asc" ? va - vb : vb - va
    })
    // Always float pinned to top
    return [...list.filter(g => g.is_pinned), ...list.filter(g => !g.is_pinned)]
  }, [galleries, search, filterStatus, filterTag, filterRole, sortField, sortDir])

  function toggleSelect(id: string) {
    const s = new Set(selected)
    s.has(id) ? s.delete(id) : s.add(id)
    setSelected(s)
  }
  function toggleSelectAll() {
    if (selected.size === filtered.length) setSelected(new Set())
    else setSelected(new Set(filtered.map(g => g.id)))
  }

  const hasFilters = search || filterStatus !== "all" || filterTag !== "all" || filterRole !== "all"

  return (
    <div className="space-y-5">

      {/* ── Toolbar ── */}
      <div className="flex flex-wrap items-center gap-3">
        {/* Search */}
        <div className="relative flex-1 min-w-[200px]">
          <span className="absolute left-3 top-1/2 -translate-y-1/2 text-[#4a4a6a] text-sm pointer-events-none">🔍</span>
          <input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Search by title or ID…"
            className="w-full bg-[#111118] border border-[#1e1e2e] rounded-xl pl-8 pr-4 py-2.5 text-sm text-white focus:border-blue-500 outline-none placeholder:text-[#4a4a6a]"
          />
          {search && (
            <button onClick={() => setSearch("")} className="absolute right-3 top-1/2 -translate-y-1/2 text-[#4a4a6a] hover:text-white text-lg leading-none">×</button>
          )}
        </div>

        {/* Status filter */}
        <div className="flex gap-1 bg-[#111118] border border-[#1e1e2e] rounded-xl p-1">
          {(["all", "active", "inactive"] as const).map((s) => (
            <button key={s} onClick={() => setFilterStatus(s)}
              className={`px-3 py-1 rounded-lg text-xs font-semibold transition-all capitalize ${filterStatus === s ? "bg-[#2563eb] text-white" : "text-[#6b6b8a] hover:text-white"}`}
            >{s}</button>
          ))}
        </div>

        {/* Tag filter */}
        {activeTags.length > 0 && (
          <select
            value={filterTag}
            onChange={e => setFilterTag(e.target.value)}
            className="bg-[#111118] border border-[#1e1e2e] rounded-xl px-3 py-2 text-xs text-white outline-none focus:border-blue-500 cursor-pointer"
          >
            <option value="all">All Tags</option>
            {activeTags.map(t => <option key={t.id} value={t.id}>{t.display}</option>)}
          </select>
        )}

        {/* Role filter */}
        <select
          value={filterRole}
          onChange={e => setFilterRole(e.target.value)}
          className="bg-[#111118] border border-[#1e1e2e] rounded-xl px-3 py-2 text-xs text-white outline-none focus:border-blue-500 cursor-pointer"
        >
          <option value="all">All Roles</option>
          {ROLES.map(r => <option key={r} value={r}>{r}</option>)}
        </select>

        {/* View toggle */}
        <div className="flex gap-1 bg-[#111118] border border-[#1e1e2e] rounded-xl p-1">
          <button onClick={() => setViewMode("list")} title="List view" className={`px-3 py-1 rounded-lg text-xs font-semibold transition-all ${viewMode === "list" ? "bg-[#2563eb] text-white" : "text-[#6b6b8a] hover:text-white"}`}>≡ List</button>
          <button onClick={() => setViewMode("grid")} title="Grid view" className={`px-3 py-1 rounded-lg text-xs font-semibold transition-all ${viewMode === "grid" ? "bg-[#2563eb] text-white" : "text-[#6b6b8a] hover:text-white"}`}>⊞ Grid</button>
          <button onClick={() => setViewMode("table")} title="Table view" className={`px-3 py-1 rounded-lg text-xs font-semibold transition-all ${viewMode === "table" ? "bg-[#2563eb] text-white" : "text-[#6b6b8a] hover:text-white"}`}>☰ Table</button>
        </div>

        {/* New Gallery */}
        <button onClick={() => setCreatingGallery(true)} className="px-4 py-2 bg-blue-600 hover:bg-blue-700 rounded-xl text-sm font-semibold flex items-center gap-2 transition-colors ml-auto">
          <span className="text-base leading-none">+</span> New Gallery
        </button>
      </div>

      {/* ── Bulk action bar (appears when items selected) ── */}
      {selected.size > 0 && (
        <div className="flex items-center gap-3 px-4 py-3 bg-[#0d1520] border border-blue-700/40 rounded-xl">
          <div className="flex items-center gap-2">
            <div className="w-5 h-5 rounded bg-blue-600 flex items-center justify-center text-[10px] font-black text-white">{selected.size}</div>
            <span className="text-sm font-semibold text-blue-300">selected</span>
          </div>
          <div className="h-4 w-px bg-[#2a2a3e] mx-1" />
          <div className="flex gap-2 flex-wrap">
            <button onClick={() => run(() => adminBulkToggleGalleries([...selected], true), `${selected.size} activated`)}
              className="px-3 py-1.5 text-xs bg-green-900/30 hover:bg-green-900/60 border border-green-700/40 rounded-lg text-green-400 font-semibold transition-colors">
              ✓ Activate
            </button>
            <button onClick={() => run(() => adminBulkToggleGalleries([...selected], false), `${selected.size} deactivated`)}
              className="px-3 py-1.5 text-xs bg-orange-900/30 hover:bg-orange-900/60 border border-orange-700/40 rounded-lg text-orange-400 font-semibold transition-colors">
              ✗ Deactivate
            </button>
            <button onClick={() => setBulkDeleteDialog(true)}
              className="px-3 py-1.5 text-xs bg-red-600 hover:bg-red-700 border border-red-500 rounded-lg text-white font-bold transition-colors shadow shadow-red-900/40">
              🗑 Delete ({selected.size})
            </button>
          </div>
          <button onClick={() => setSelected(new Set())} className="ml-auto px-2 py-1 text-xs text-[#4a4a6a] hover:text-white rounded transition-colors">
            ✕ Clear
          </button>
        </div>
      )}

      {/* ── Status line + clear filters ── */}
      <div className="flex items-center justify-between">
        <div className="text-xs text-[#4a4a6a]">
          Showing <span className="text-white font-semibold">{filtered.length}</span> of <span className="text-white">{galleries.length}</span> galleries
          {filterStatus !== "all" && <span className="ml-1 text-blue-400">· {filterStatus}</span>}
          {filterTag !== "all" && <span className="ml-1 text-purple-400">· tag filtered</span>}
        </div>
        {hasFilters && (
          <button
            onClick={() => { setSearch(""); setFilterStatus("all"); setFilterTag("all"); setFilterRole("all") }}
            className="text-xs text-[#4a4a6a] hover:text-red-400 transition-colors"
          >
            ✕ Clear filters
          </button>
        )}
      </div>

      {/* ─── LIST VIEW (default) ─── */}
      {viewMode === "list" && (
        <div className="bg-[#111118] border border-[#1e1e2e] rounded-xl overflow-hidden divide-y divide-[#1e1e2e]">
          {/* List header */}
          <div className="grid items-center gap-4 px-4 py-2.5 bg-[#0d0d15]" style={{ gridTemplateColumns: "2rem 3rem 1fr 6rem 5rem 5rem 4rem 7rem 9rem" }}>
            <div>
              <input
                type="checkbox"
                checked={selected.size === filtered.length && filtered.length > 0}
                onChange={toggleSelectAll}
                className="accent-blue-500 cursor-pointer"
              />
            </div>
            <div />
            <button onClick={() => toggleSort("title")} className="flex items-center text-[10px] font-bold text-[#4a4a6a] uppercase tracking-widest hover:text-white transition-colors text-left">
              Gallery <SortIcon field="title" />
            </button>
            <div className="text-[10px] font-bold text-[#4a4a6a] uppercase tracking-widest">Role</div>
            <button onClick={() => toggleSort("views")} className="flex items-center gap-0.5 text-[10px] font-bold text-[#4a4a6a] uppercase tracking-widest hover:text-white transition-colors">
              Views <SortIcon field="views" />
            </button>
            <button onClick={() => toggleSort("copies")} className="flex items-center gap-0.5 text-[10px] font-bold text-[#4a4a6a] uppercase tracking-widest hover:text-white transition-colors">
              Copies <SortIcon field="copies" />
            </button>
            <button onClick={() => toggleSort("rate")} className="flex items-center gap-0.5 text-[10px] font-bold text-[#4a4a6a] uppercase tracking-widest hover:text-white transition-colors">
              Rate <SortIcon field="rate" />
            </button>
            <div className="text-[10px] font-bold text-[#4a4a6a] uppercase tracking-widest">Status</div>
            <div className="text-[10px] font-bold text-[#4a4a6a] uppercase tracking-widest text-right">Actions</div>
          </div>

          {/* List rows */}
          {filtered.length === 0 && (
            <div className="py-16 text-center text-[#4a4a6a]">
              <div className="text-4xl mb-2 opacity-20">🖼</div>
              <div className="text-sm">No galleries found</div>
              {hasFilters && <div className="text-xs mt-1">Try adjusting your filters</div>}
            </div>
          )}

          {filtered.map((g) => {
            const copyRate = g.stats.total_views > 0 ? ((g.stats.total_copies / g.stats.total_views) * 100).toFixed(1) : "0.0"
            const rateNum = parseFloat(copyRate)
            const activeLinks = g.links.filter(l => l.is_active).length
            const isSelected = selected.has(g.id)
            const tagObjs = tags.filter(t => g.tags.includes(t.id))

            return (
              <div key={g.id}>
                <div
                  className={`grid items-center gap-4 px-4 py-3 transition-colors hover:bg-[#0d0d15] ${isSelected ? "bg-blue-950/20" : ""}`}
                  style={{ gridTemplateColumns: "2rem 3rem 1fr 6rem 5rem 5rem 4rem 7rem 9rem" }}
                >
                  {/* Checkbox */}
                  <div>
                    <div
                      onClick={() => toggleSelect(g.id)}
                      className={`w-4 h-4 rounded border-2 flex items-center justify-center cursor-pointer transition-all ${
                        isSelected ? "bg-blue-600 border-blue-500" : "border-[#3a3a5a] hover:border-blue-500"
                      }`}
                    >
                      {isSelected && <span className="text-[9px] text-white font-black">✓</span>}
                    </div>
                  </div>

                  {/* Thumbnail */}
                  <div>
                    <img
                      src={g.thumbnail || "/placeholder.jpg"}
                      alt={g.title}
                      className="w-10 h-10 rounded-lg object-cover border border-[#1e1e2e]"
                      onError={(e) => { e.currentTarget.src = "/placeholder.jpg"; e.currentTarget.style.opacity = "0.3" }}
                    />
                  </div>

                  {/* Title + meta */}
                  <div className="min-w-0">
                    <div className="flex items-center gap-1.5 min-w-0">
                      {g.is_pinned && <span className="text-[10px] shrink-0">📌</span>}
                      <span className="text-sm font-semibold text-white truncate">{g.title}</span>
                    </div>
                    <div className="flex items-center gap-2 mt-0.5">
                      <span className="text-[10px] text-[#4a4a6a] font-mono truncate">{g.id}</span>
                      {tagObjs.slice(0, 2).map(t => (
                        <span key={t.id} style={{ color: t.color, backgroundColor: t.color + "18" }} className="text-[9px] font-bold px-1 py-0.5 rounded shrink-0">{t.display}</span>
                      ))}
                      {tagObjs.length > 2 && <span className="text-[9px] text-[#4a4a6a] shrink-0">+{tagObjs.length - 2}</span>}
                    </div>
                  </div>

                  {/* Role */}
                  <div><RoleBadge role={g.access.min_role_name} /></div>

                  {/* Views */}
                  <div className="text-xs font-semibold text-white">{g.stats.total_views.toLocaleString()}</div>

                  {/* Copies */}
                  <div className="text-xs text-[#6b6b8a]">{g.stats.total_copies}</div>

                  {/* Rate */}
                  <div className={`text-xs font-bold ${rateNum >= 5 ? "text-emerald-400" : rateNum >= 2 ? "text-yellow-400" : "text-[#4a4a6a]"}`}>
                    {copyRate}%
                  </div>

                  {/* Status */}
                  <div>
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${g.is_active ? "bg-green-900/40 text-green-400" : "bg-red-900/40 text-red-400"}`}>
                      {g.is_active ? "Active" : "Inactive"}
                    </span>
                  </div>

                  {/* Actions */}
                  <div className="flex items-center justify-end gap-1">
                    <button onClick={() => setEditingGallery(g)} className="px-2 py-1 text-[10px] bg-blue-900/30 hover:bg-blue-900/60 rounded text-blue-400 transition-colors font-semibold">Edit</button>
                    <button
                      onClick={() => setExpandedLinks(expandedLinks === g.id ? null : g.id)}
                      className={`px-2 py-1 text-[10px] rounded transition-colors font-semibold ${expandedLinks === g.id ? "bg-[#2a2a3e] text-white" : "bg-[#1e1e2e] hover:bg-[#2a2a3e] text-[#6b6b8a] hover:text-white"}`}
                    >
                      {expandedLinks === g.id ? "▲" : `▼ ${g.links.length}`}
                    </button>
                    <button
                      onClick={() => run(() => adminUpdateGallery(g.id, { is_active: !g.is_active }), g.is_active ? "Deactivated" : "Activated")}
                      className={`px-2 py-1 text-[10px] rounded transition-colors font-semibold ${g.is_active ? "bg-orange-900/20 hover:bg-orange-900/40 text-orange-400" : "bg-green-900/20 hover:bg-green-900/40 text-green-400"}`}
                    >
                      {g.is_active ? "Off" : "On"}
                    </button>
                    <button onClick={() => setDeleteDialog(g)} className="px-2 py-1 text-[10px] bg-red-900/20 hover:bg-red-900/50 rounded text-red-400 transition-colors">🗑</button>
                  </div>
                </div>

                {/* Expanded links panel */}
                {expandedLinks === g.id && (
                  <div className="border-t border-[#1e1e2e] bg-[#080810]">
                    <LinksPanel gallery={g} run={run} notify={notify} />
                  </div>
                )}
              </div>
            )
          })}
        </div>
      )}

      {/* ─── GRID VIEW ─── */}
      {viewMode === "grid" && (
        <div className="flex flex-col gap-4">
          {/* Grid toolbar with Select All */}
          <div className="flex items-center gap-3">
            <label className="flex items-center gap-2 cursor-pointer select-none">
              <input
                type="checkbox"
                checked={selected.size === filtered.length && filtered.length > 0}
                onChange={toggleSelectAll}
                className="accent-blue-500 cursor-pointer w-4 h-4"
              />
              <span className="text-xs text-[#6b6b8a] font-semibold">
                {selected.size === filtered.length && filtered.length > 0 ? "Deselect All" : "Select All"}
              </span>
            </label>
            {selected.size > 0 && (
              <span className="text-xs text-blue-400">{selected.size} of {filtered.length} selected</span>
            )}
          </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
          {filtered.map((g) => {
            const copyRate = g.stats.total_views > 0 ? ((g.stats.total_copies / g.stats.total_views) * 100).toFixed(1) : "0.0"
            const tagObjs = tags.filter((t) => g.tags.includes(t.id))
            const isSelected = selected.has(g.id)

            return (
              <div
                key={g.id}
                className={`group relative bg-[#111118] border rounded-xl overflow-hidden transition-all duration-200 hover:shadow-xl hover:shadow-black/30 ${
                  isSelected ? "border-blue-500/70 ring-1 ring-blue-500/30 shadow-lg shadow-blue-900/20" :
                  g.is_pinned ? "border-yellow-500/30 hover:border-yellow-500/50" :
                  "border-[#1e1e2e] hover:border-[#2a2a3e]"
                }`}
              >
                {/* ── Thumbnail */}
                <div className="relative h-40 bg-[#0d0d15] overflow-hidden">
                  <img
                    src={g.thumbnail || "/placeholder.jpg"}
                    alt={g.title}
                    className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                    onError={(e) => { e.currentTarget.src = "/placeholder.jpg"; e.currentTarget.style.opacity = "0.3" }}
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/10 to-transparent" />

                  {/* Status badges — top left */}
                  <div className="absolute top-2 left-2 flex gap-1">
                    {!g.is_active && (
                      <span className="bg-red-900/90 text-red-300 text-[9px] font-bold px-1.5 py-0.5 rounded backdrop-blur-sm border border-red-700/40">INACTIVE</span>
                    )}
                    {g.is_pinned && (
                      <span className="bg-yellow-900/90 text-yellow-300 text-[9px] font-bold px-1.5 py-0.5 rounded backdrop-blur-sm border border-yellow-700/40">📌 PINNED</span>
                    )}
                  </div>

                  {/* Checkbox — top right */}
                  <div className="absolute top-2 right-2">
                    <div
                      onClick={(e) => { e.stopPropagation(); toggleSelect(g.id) }}
                      className={`w-5 h-5 rounded border-2 flex items-center justify-center cursor-pointer transition-all ${
                        isSelected ? "bg-blue-600 border-blue-500" : "bg-black/40 border-white/30 hover:border-white/60"
                      }`}
                    >
                      {isSelected && <span className="text-[10px] text-white font-bold">✓</span>}
                    </div>
                  </div>

                  {/* View count — bottom left in thumbnail */}
                  <div className="absolute bottom-2 left-2 flex items-center gap-1.5">
                    <span className="text-[10px] text-white/80 font-semibold bg-black/50 px-1.5 py-0.5 rounded backdrop-blur-sm">
                      👁 {g.stats.total_views.toLocaleString()}
                    </span>
                    <span className="text-[10px] text-emerald-300 font-bold bg-black/50 px-1.5 py-0.5 rounded backdrop-blur-sm">
                      {copyRate}%
                    </span>
                  </div>

                  {/* Quick actions — slide up on hover */}
                  <div className="absolute bottom-0 left-0 right-0 flex gap-1 p-2 translate-y-full group-hover:translate-y-0 transition-transform duration-200">
                    <button onClick={() => setEditingGallery(g)} className="flex-1 py-1.5 text-[10px] font-bold bg-blue-600/95 hover:bg-blue-600 rounded text-white transition-colors">✏ Edit</button>
                    <button onClick={() => setExpandedLinks(expandedLinks === g.id ? null : g.id)} className="flex-1 py-1.5 text-[10px] font-bold bg-[#1e1e2e]/95 hover:bg-[#2a2a3e] rounded text-white transition-colors">🔗 Links ({g.links.length})</button>
                    <button onClick={() => run(() => adminUpdateGallery(g.id, { is_active: !g.is_active }), g.is_active ? "Deactivated" : "Activated")}
                      className={`py-1.5 px-2 text-[10px] font-bold rounded transition-colors ${g.is_active ? "bg-orange-900/80 hover:bg-orange-900 text-orange-300" : "bg-green-900/80 hover:bg-green-900 text-green-300"}`}>
                      {g.is_active ? "Hide" : "Show"}
                    </button>
                    <button onClick={() => setDeleteDialog(g)} className="py-1.5 px-2 text-[10px] font-bold bg-red-900/80 hover:bg-red-900 rounded text-red-300 transition-colors">Del</button>
                  </div>
                </div>

                {/* ── Card Body */}
                <div className="p-3 space-y-2.5">
                  <div>
                    <div className="text-sm font-bold text-white truncate leading-tight">{g.title}</div>
                    <div className="text-[10px] text-[#4a4a6a] font-mono truncate mt-0.5">{g.id}</div>
                  </div>

                  {/* Tags */}
                  {tagObjs.length > 0 && (
                    <div className="flex gap-1 flex-wrap">
                      {tagObjs.slice(0, 3).map((t) => (
                        <span key={t.id} style={{ backgroundColor: t.color + "22", color: t.color, borderColor: t.color + "44" }} className="text-[9px] font-bold px-1.5 py-0.5 rounded border">{t.display}</span>
                      ))}
                      {tagObjs.length > 3 && <span className="text-[9px] text-[#4a4a6a]">+{tagObjs.length - 3}</span>}
                    </div>
                  )}

                  {/* Stats row */}
                  <div className="grid grid-cols-3 gap-1 text-center">
                    <div className="bg-[#0d0d15] rounded-lg py-1.5">
                      <div className="text-[9px] text-[#4a4a6a] uppercase">Views</div>
                      <div className="text-xs font-bold text-white">{g.stats.total_views.toLocaleString()}</div>
                    </div>
                    <div className="bg-[#0d0d15] rounded-lg py-1.5">
                      <div className="text-[9px] text-[#4a4a6a] uppercase">Copies</div>
                      <div className="text-xs font-bold text-blue-400">{g.stats.total_copies}</div>
                    </div>
                    <div className="bg-[#0d0d15] rounded-lg py-1.5">
                      <div className="text-[9px] text-[#4a4a6a] uppercase">Links</div>
                      <div className="text-xs font-bold text-white">{g.links.length}</div>
                    </div>
                  </div>

                  {/* Access + pin/reset row */}
                  <div className="flex items-center justify-between pt-1 border-t border-[#1e1e2e]">
                    <RoleBadge role={g.access.min_role_name} />
                    <div className="flex gap-1">
                      <button
                        onClick={() => run(() => adminUpdateGallery(g.id, { is_pinned: !g.is_pinned }), g.is_pinned ? "Unpinned" : "Pinned")}
                        title={g.is_pinned ? "Unpin" : "Pin to top"}
                        className={`text-[10px] px-1.5 py-0.5 rounded transition-colors ${g.is_pinned ? "bg-yellow-900/30 text-yellow-400 hover:bg-yellow-900/50" : "bg-[#1e1e2e] text-[#4a4a6a] hover:text-white"}`}
                      >
                        {g.is_pinned ? "📌" : "📍"}
                      </button>
                      <button
                        onClick={() => setDeleteDialog(g)}
                        title="Delete gallery"
                        className="text-[10px] px-1.5 py-0.5 bg-[#1e1e2e] hover:bg-red-900/30 hover:text-red-400 text-[#4a4a6a] rounded transition-colors"
                      >
                        🗑
                      </button>
                    </div>
                  </div>
                </div>

                {/* ── Inline Links Panel */}
                {expandedLinks === g.id && (
                  <div className="border-t border-[#1e1e2e]">
                    <LinksPanel gallery={g} run={run} notify={notify} />
                  </div>
                )}
              </div>
            )
          })}

          {filtered.length === 0 && (
            <div className="col-span-full text-center py-20 text-[#4a4a6a]">
              <div className="text-5xl mb-3 opacity-30">🖼</div>
              <div className="text-sm font-semibold mb-1">No galleries found</div>
              {hasFilters && <div className="text-xs">Try adjusting your filters</div>}
            </div>
          )}
        </div>
        </div>
      )}

      {/* ─── TABLE VIEW (with sortable columns) ─── */}
      {viewMode === "table" && (
        <div className="bg-[#111118] border border-[#1e1e2e] rounded-xl overflow-hidden">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-[#1e1e2e] bg-[#0d0d15]">
                <th className="w-10 px-4 py-3">
                  <input
                    type="checkbox"
                    checked={selected.size === filtered.length && filtered.length > 0}
                    onChange={toggleSelectAll}
                    className="accent-blue-500 cursor-pointer"
                  />
                </th>
                <th className="px-4 py-3 text-left">
                  <button onClick={() => toggleSort("title")} className="flex items-center text-xs font-bold text-[#4a4a6a] uppercase tracking-widest hover:text-white transition-colors">
                    Gallery <SortIcon field="title" />
                  </button>
                </th>
                <th className="px-4 py-3 text-left text-xs font-bold text-[#4a4a6a] uppercase tracking-widest">Access</th>
                <th className="px-4 py-3 text-center">
                  <button onClick={() => toggleSort("views")} className="flex items-center gap-0.5 text-xs font-bold text-[#4a4a6a] uppercase tracking-widest hover:text-white transition-colors mx-auto">
                    Views <SortIcon field="views" />
                  </button>
                </th>
                <th className="px-4 py-3 text-center">
                  <button onClick={() => toggleSort("rate")} className="flex items-center gap-0.5 text-xs font-bold text-[#4a4a6a] uppercase tracking-widest hover:text-white transition-colors mx-auto">
                    Rate <SortIcon field="rate" />
                  </button>
                </th>
                <th className="px-4 py-3 text-center">
                  <button onClick={() => toggleSort("links")} className="flex items-center gap-0.5 text-xs font-bold text-[#4a4a6a] uppercase tracking-widest hover:text-white transition-colors mx-auto">
                    Links <SortIcon field="links" />
                  </button>
                </th>
                <th className="px-4 py-3 text-center text-xs font-bold text-[#4a4a6a] uppercase tracking-widest">Status</th>
                <th className="px-4 py-3 text-right text-xs font-bold text-[#4a4a6a] uppercase tracking-widest">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-[#1e1e2e]">
              {filtered.map((g) => {
                const copyRate = g.stats.total_views > 0 ? ((g.stats.total_copies / g.stats.total_views) * 100).toFixed(1) : "0.0"
                const activeLinks = g.links.filter(l => l.is_active).length
                return (
                  <>
                    <tr key={g.id} className={`hover:bg-[#0d0d15] transition-colors ${selected.has(g.id) ? "bg-blue-950/20" : ""}`}>
                      <td className="px-4 py-3">
                        <input type="checkbox" checked={selected.has(g.id)} onChange={() => toggleSelect(g.id)} className="accent-blue-500 cursor-pointer" />
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-3">
                          <img src={g.thumbnail || "/placeholder.jpg"} alt="" className="w-10 h-10 rounded-lg object-cover border border-[#1e1e2e] shrink-0"
                            onError={(e) => { e.currentTarget.style.opacity = "0.2" }} />
                          <div>
                            <div className="font-semibold text-white flex items-center gap-1.5">
                              {g.title}
                              {g.is_pinned && <span className="text-[10px]">📌</span>}
                            </div>
                            <div className="text-[10px] text-[#4a4a6a] font-mono">{g.id}</div>
                            {g.tags.length > 0 && (
                              <div className="flex gap-1 mt-1 flex-wrap">
                                {tags.filter(t => g.tags.includes(t.id)).slice(0, 2).map(t => (
                                  <span key={t.id} style={{ color: t.color, backgroundColor: t.color + "22" }} className="text-[9px] font-bold px-1 py-0.5 rounded">{t.display}</span>
                                ))}
                              </div>
                            )}
                          </div>
                        </div>
                      </td>
                      <td className="px-4 py-3"><RoleBadge role={g.access.min_role_name} /></td>
                      <td className="px-4 py-3 text-center">
                        <div className="text-xs text-white font-semibold">{g.stats.total_views.toLocaleString()}</div>
                        <div className="text-[10px] text-[#4a4a6a]">{g.stats.total_copies} copies</div>
                      </td>
                      <td className="px-4 py-3 text-center">
                        <span className={`text-xs font-bold ${parseFloat(copyRate) >= 5 ? "text-emerald-400" : parseFloat(copyRate) >= 2 ? "text-yellow-400" : "text-[#4a4a6a]"}`}>{copyRate}%</span>
                      </td>
                      <td className="px-4 py-3 text-center">
                        <span className="text-xs text-white">{activeLinks}</span>
                        {activeLinks < g.links.length && <span className="text-[10px] text-red-400 ml-1">/{g.links.length}</span>}
                      </td>
                      <td className="px-4 py-3 text-center">
                        <span className={`text-xs font-bold px-2 py-0.5 rounded-full ${g.is_active ? "bg-green-900/40 text-green-400" : "bg-red-900/40 text-red-400"}`}>
                          {g.is_active ? "Active" : "Inactive"}
                        </span>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center justify-end gap-1 flex-wrap">
                          <button onClick={() => setEditingGallery(g)} className="px-2 py-1 text-xs bg-blue-900/30 hover:bg-blue-900/60 rounded text-blue-400 transition-colors font-medium">Edit</button>
                          <button onClick={() => setExpandedLinks(expandedLinks === g.id ? null : g.id)} className={`px-2 py-1 text-xs rounded transition-colors font-medium ${expandedLinks === g.id ? "bg-[#2a2a3e] text-white" : "bg-[#1e1e2e] hover:bg-[#2a2a3e] text-[#6b6b8a] hover:text-white"}`}>
                            {expandedLinks === g.id ? "▲ Links" : "▼ Links"}
                          </button>
                          <button onClick={() => run(() => adminUpdateGallery(g.id, { is_active: !g.is_active }), g.is_active ? "Deactivated" : "Activated")}
                            className={`px-2 py-1 text-xs rounded transition-colors font-medium ${g.is_active ? "bg-orange-900/30 hover:bg-orange-900/50 text-orange-400" : "bg-green-900/30 hover:bg-green-900/50 text-green-400"}`}>
                            {g.is_active ? "Disable" : "Enable"}
                          </button>
                          <button onClick={() => run(() => adminUpdateGallery(g.id, { is_pinned: !g.is_pinned }), g.is_pinned ? "Unpinned" : "Pinned")}
                            className="px-2 py-1 text-xs bg-[#1e1e2e] hover:bg-[#2a2a3e] rounded text-[#6b6b8a] hover:text-white transition-colors">
                            {g.is_pinned ? "Unpin" : "Pin"}
                          </button>
                          <button onClick={() => run(() => adminResetStats(g.id), "Stats reset")} className="px-2 py-1 text-xs bg-yellow-900/20 hover:bg-yellow-900/40 rounded text-yellow-600 hover:text-yellow-400 transition-colors">Reset</button>
                          <button onClick={() => setDeleteDialog(g)} className="px-2 py-1 text-xs bg-red-900/20 hover:bg-red-900/50 rounded text-red-400 transition-colors">Del</button>
                        </div>
                      </td>
                    </tr>
                    {expandedLinks === g.id && (
                      <tr key={`${g.id}-links`}>
                        <td colSpan={8} className="px-4 pb-4 bg-[#0a0a0f]">
                          <LinksPanel gallery={g} run={run} notify={notify} />
                        </td>
                      </tr>
                    )}
                  </>
                )
              })}
              {filtered.length === 0 && (
                <tr><td colSpan={8} className="px-4 py-14 text-center text-[#4a4a6a]">No galleries found</td></tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {/* Edit Gallery Modal */}
      {editingGallery && (
        <EditGalleryModal gallery={editingGallery} tags={tags} onClose={() => setEditingGallery(null)} run={run} notify={notify} />
      )}

      {/* Create Gallery Modal */}
      {creatingGallery && (
        <CreateGalleryModal tags={tags} onClose={() => setCreatingGallery(false)} run={run} notify={notify} />
      )}

      {/* Delete Confirm Dialog */}
      {deleteDialog && (
        <ConfirmDialog
          title={`Delete "${deleteDialog.title}"?`}
          message="This action is permanent and cannot be undone. All links inside will be removed."
          confirmLabel="Delete Gallery"
          danger
          onConfirm={() => { run(() => adminDeleteGallery(deleteDialog.id), "Gallery deleted"); setDeleteDialog(null) }}
          onCancel={() => setDeleteDialog(null)}
        />
      )}

      {/* Bulk Delete Confirm Dialog */}
      {bulkDeleteDialog && (
        <ConfirmDialog
          title={`Delete ${selected.size} galleries?`}
          message={`This will permanently delete all ${selected.size} selected galleries and their links. This cannot be undone.`}
          confirmLabel={`Delete ${selected.size} Galleries`}
          danger
          onConfirm={async () => {
            const ids = [...selected]
            await adminBulkDeleteGalleries(ids)
            notify(`${ids.length} galleries deleted`)
            setSelected(new Set())
            setBulkDeleteDialog(false)
          }}
          onCancel={() => setBulkDeleteDialog(false)}
        />
      )}
    </div>
  )
}

// ─── Links Panel (improved) ────────────────────────────────────────────────────
function LinksPanel({ gallery, run, notify }: { gallery: Gallery; run: (fn: () => Promise<{ ok: boolean }>, msg: string) => void; notify: (msg: string, type?: "ok" | "err") => void }) {
  const [showAdd, setShowAdd] = useState(false)
  const [editingLink, setEditingLink] = useState<string | null>(null)
  const [linkForm, setLinkForm] = useState({ label: "", url: "", copyLimit: 5, minLevel: gallery.access.min_hierarchy_level })
  const [editForm, setEditForm] = useState<{ label: string; url: string; copyLimit: number; minLevel: number }>({ label: "", url: "", copyLimit: 5, minLevel: gallery.access.min_hierarchy_level })

  function startEdit(link: typeof gallery.links[0]) {
    setEditingLink(link.id)
    setEditForm({ label: link.label, url: link.url, copyLimit: link.copy_limit_per_user, minLevel: link.accessible_by_min_level })
  }

  const NULL_REASONS = [
    { value: "link_dead", label: "Link Dead" },
    { value: "moved", label: "Moved" },
    { value: "owner_request", label: "Owner Request" },
  ]

  return (
    <div className="mt-2 border border-[#1e1e2e] rounded-xl overflow-hidden">
      <div className="px-4 py-3 bg-[#0d0d15] border-b border-[#1e1e2e] flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="text-xs font-bold text-[#6b6b8a] uppercase tracking-widest">🔗 {gallery.title}</div>
          <span className="text-[10px] text-[#4a4a6a]">
            {gallery.links.filter(l => l.is_active).length}/{gallery.links.length} active
          </span>
        </div>
        <button onClick={() => setShowAdd(!showAdd)} className="text-xs px-3 py-1.5 bg-blue-600 hover:bg-blue-700 rounded-lg font-semibold transition-colors">
          {showAdd ? "✕ Cancel" : "+ Add Link"}
        </button>
      </div>

      {/* Add form */}
      {showAdd && (
        <div className="px-4 py-4 bg-[#080810] border-b border-[#1e1e2e] space-y-3">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            <div>
              <label className="text-[10px] text-[#4a4a6a] block mb-1 uppercase tracking-widest">Label</label>
              <input value={linkForm.label} onChange={(e) => setLinkForm({ ...linkForm, label: e.target.value })}
                className="w-full bg-[#111118] border border-[#1e1e2e] rounded-lg px-2.5 py-2 text-xs text-white outline-none focus:border-blue-500 placeholder:text-[#4a4a6a]"
                placeholder="x.com/user" />
            </div>
            <div className="md:col-span-2">
              <label className="text-[10px] text-[#4a4a6a] block mb-1 uppercase tracking-widest">URL</label>
              <input value={linkForm.url} onChange={(e) => setLinkForm({ ...linkForm, url: e.target.value })}
                className="w-full bg-[#111118] border border-[#1e1e2e] rounded-lg px-2.5 py-2 text-xs text-white outline-none focus:border-blue-500 placeholder:text-[#4a4a6a]"
                placeholder="https://…" />
            </div>
            <div>
              <label className="text-[10px] text-[#4a4a6a] block mb-1 uppercase tracking-widest">Copy Limit</label>
              <input type="number" min={1} max={999} value={linkForm.copyLimit}
                onChange={(e) => setLinkForm({ ...linkForm, copyLimit: Math.min(999, Math.max(1, Number(e.target.value))) })}
                className="w-full bg-[#111118] border border-[#1e1e2e] rounded-lg px-2.5 py-2 text-xs text-white outline-none focus:border-blue-500" />
            </div>
          </div>
          <div>
            <label className="text-[10px] text-[#4a4a6a] block mb-1 uppercase tracking-widest">Min Role</label>
            <div className="flex gap-2 flex-wrap">
              {ROLES.map((r) => (
                <button key={r} onClick={() => setLinkForm({ ...linkForm, minLevel: ROLE_LEVELS[r] })}
                  style={{
                    borderColor: linkForm.minLevel === ROLE_LEVELS[r] ? ROLE_COLORS[r] : "#1e1e2e",
                    color: linkForm.minLevel === ROLE_LEVELS[r] ? ROLE_COLORS[r] : "#6b6b8a",
                    backgroundColor: linkForm.minLevel === ROLE_LEVELS[r] ? ROLE_COLORS[r] + "22" : "transparent",
                  }}
                  className="px-2.5 py-1 rounded-lg border text-[10px] font-bold transition-all">{r}</button>
              ))}
            </div>
          </div>
          <div className="flex gap-2">
            <button
              onClick={() => {
                if (!linkForm.label || !linkForm.url) { notify("Label & URL required", "err"); return }
                run(() => adminAddLink(gallery.id, linkForm), "Link added")
                setShowAdd(false)
                setLinkForm({ label: "", url: "", copyLimit: 5, minLevel: gallery.access.min_hierarchy_level })
              }}
              className="px-4 py-1.5 bg-blue-600 hover:bg-blue-700 rounded-lg text-xs font-semibold transition-colors"
            >Add Link</button>
          </div>
        </div>
      )}

      {/* Links table */}
      <table className="w-full text-xs">
        <thead>
          <tr className="border-b border-[#1e1e2e] bg-[#0d0d15]">
            <th className="px-4 py-2 text-left text-[10px] font-bold text-[#4a4a6a] uppercase tracking-widest">Label</th>
            <th className="px-4 py-2 text-left text-[10px] font-bold text-[#4a4a6a] uppercase tracking-widest">URL</th>
            <th className="px-4 py-2 text-center text-[10px] font-bold text-[#4a4a6a] uppercase tracking-widest">Min Role</th>
            <th className="px-4 py-2 text-center text-[10px] font-bold text-[#4a4a6a] uppercase tracking-widest">Limit</th>
            <th className="px-4 py-2 text-center text-[10px] font-bold text-[#4a4a6a] uppercase tracking-widest">Copies</th>
            <th className="px-4 py-2 text-center text-[10px] font-bold text-[#4a4a6a] uppercase tracking-widest">Status</th>
            <th className="px-4 py-2 text-right text-[10px] font-bold text-[#4a4a6a] uppercase tracking-widest">Actions</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-[#1e1e2e]">
          {gallery.links.length === 0 && (
            <tr><td colSpan={6} className="px-4 py-8 text-center text-[#4a4a6a]">No links yet — add one above</td></tr>
          )}
          {gallery.links.map((link) => (
            <>
              <tr key={link.id} className={`hover:bg-[#0d0d15] transition-colors ${!link.is_active ? "opacity-60" : ""}`}>
                <td className="px-4 py-2.5 text-white font-semibold">{link.label}</td>
                <td className="px-4 py-2.5 text-blue-400 max-w-[220px]">
                  <a href={link.url} target="_blank" rel="noopener noreferrer" className="hover:underline truncate block" title={link.url}>
                    {link.url.length > 42 ? link.url.slice(0, 42) + "…" : link.url}
                  </a>
                </td>
                <td className="px-4 py-2.5 text-center">
                  {(() => {
                    const roleName = Object.entries(ROLE_LEVELS).find(([, v]) => v === link.accessible_by_min_level)?.[0]
                    return roleName
                      ? <span className="px-2 py-0.5 rounded-full text-[10px] font-bold border" style={{ borderColor: ROLE_COLORS[roleName] + "44", color: ROLE_COLORS[roleName], backgroundColor: ROLE_COLORS[roleName] + "22" }}>{roleName}</span>
                      : <span className="text-[#4a4a6a] text-[10px]">Lv.{link.accessible_by_min_level}</span>
                  })()}
                </td>
                <td className="px-4 py-2.5 text-center text-[#6b6b8a]">{link.copy_limit_per_user}×</td>
                <td className="px-4 py-2.5 text-center">
                  <span className={link.total_copies > 0 ? "text-blue-400 font-bold" : "text-[#4a4a6a]"}>{link.total_copies}</span>
                </td>
                <td className="px-4 py-2.5 text-center">
                  <span className={`font-bold px-2 py-0.5 rounded-full text-[10px] ${link.is_active ? "bg-green-900/40 text-green-400" : "bg-red-900/40 text-red-400"}`}>
                    {link.is_active ? "Live" : link.null_reason ?? "Off"}
                  </span>
                </td>
                <td className="px-4 py-2.5">
                  <div className="flex items-center justify-end gap-1">
                    <button onClick={() => startEdit(link)} className="px-2 py-0.5 bg-[#1e1e2e] hover:bg-[#2a2a3e] rounded text-[#6b6b8a] hover:text-white transition-colors">Edit</button>
                    <button
                      onClick={() => run(() => adminUpdateLink(gallery.id, link.id, { is_active: !link.is_active, null_reason: link.is_active ? "link_dead" : null }), link.is_active ? "Disabled" : "Enabled")}
                      className={`px-2 py-0.5 rounded transition-colors ${link.is_active ? "bg-orange-900/30 hover:bg-orange-900/50 text-orange-400" : "bg-green-900/30 hover:bg-green-900/50 text-green-400"}`}>
                      {link.is_active ? "Disable" : "Enable"}
                    </button>
                    <button onClick={() => run(() => adminDeleteLink(gallery.id, link.id), "Link deleted")} className="px-2 py-0.5 bg-red-900/20 hover:bg-red-900/40 rounded text-red-400 transition-colors">Del</button>
                  </div>
                </td>
              </tr>
              {/* Inline edit row */}
              {editingLink === link.id && (
                <tr key={`${link.id}-edit`} className="bg-[#0a0a10]">
                  <td colSpan={7} className="px-4 py-3">
                    <div className="grid grid-cols-3 gap-3 items-end">
                      <div>
                        <label className="text-[10px] text-[#4a4a6a] block mb-1">Label</label>
                        <input value={editForm.label} onChange={e => setEditForm({ ...editForm, label: e.target.value })}
                          className="w-full bg-[#111118] border border-[#1e1e2e] rounded-lg px-2.5 py-1.5 text-xs text-white outline-none focus:border-blue-500" />
                      </div>
                      <div>
                        <label className="text-[10px] text-[#4a4a6a] block mb-1">URL</label>
                        <input value={editForm.url} onChange={e => setEditForm({ ...editForm, url: e.target.value })}
                          className="w-full bg-[#111118] border border-[#1e1e2e] rounded-lg px-2.5 py-1.5 text-xs text-white outline-none focus:border-blue-500" />
                      </div>
                      <div>
                        <label className="text-[10px] text-[#4a4a6a] block mb-1">Copy Limit</label>
                        <input type="number" min={1} max={999} value={editForm.copyLimit}
                          onChange={e => setEditForm({ ...editForm, copyLimit: Math.min(999, Math.max(1, Number(e.target.value))) })}
                          className="w-full bg-[#111118] border border-[#1e1e2e] rounded-lg px-2.5 py-1.5 text-xs text-white outline-none focus:border-blue-500" />
                      </div>
                    </div>
                    <div className="mt-3">
                      <label className="text-[10px] text-[#4a4a6a] block mb-1.5 uppercase tracking-widest">Min Role</label>
                      <div className="flex gap-2 flex-wrap">
                        {ROLES.map((r) => (
                          <button key={r} onClick={() => setEditForm({ ...editForm, minLevel: ROLE_LEVELS[r] })}
                            style={{
                              borderColor: editForm.minLevel === ROLE_LEVELS[r] ? ROLE_COLORS[r] : "#1e1e2e",
                              color: editForm.minLevel === ROLE_LEVELS[r] ? ROLE_COLORS[r] : "#6b6b8a",
                              backgroundColor: editForm.minLevel === ROLE_LEVELS[r] ? ROLE_COLORS[r] + "22" : "transparent",
                            }}
                            className="px-2.5 py-1 rounded-lg border text-[10px] font-bold transition-all">{r}</button>
                        ))}
                      </div>
                    </div>
                    <div className="flex gap-2 mt-2">
                      <button
                        onClick={() => {
                          if (!editForm.label || !editForm.url) { notify("Label & URL required", "err"); return }
                          run(() => adminUpdateLink(gallery.id, link.id, { label: editForm.label, url: editForm.url, copy_limit_per_user: editForm.copyLimit, accessible_by_min_level: editForm.minLevel }), "Link updated")
                          setEditingLink(null)
                        }}
                        className="px-3 py-1 bg-blue-600 hover:bg-blue-700 rounded text-[10px] font-semibold transition-colors">Save</button>
                      <button onClick={() => setEditingLink(null)} className="px-3 py-1 text-[#4a4a6a] hover:text-white rounded text-[10px] transition-colors">Cancel</button>
                    </div>
                  </td>
                </tr>
              )}
            </>
          ))}
        </tbody>
      </table>
    </div>
  )
}

// ─── Users Tab ─────────────────────────────────────────────────────────────────
function UsersTab({ users, run, notify }: { users: AppUser[]; run: (fn: () => Promise<{ ok: boolean }>, msg: string) => void; notify: (msg: string, type?: "ok" | "err") => void }) {
  const [search, setSearch] = useState("")
  const [expandedUser, setExpandedUser] = useState<string | null>(null)
  const [banDialog, setBanDialog] = useState<AppUser | null>(null)
  const [banReason, setBanReason] = useState("")

  const filtered = users.filter(
    (u) => u.discord_tag.toLowerCase().includes(search.toLowerCase()) || u.username.toLowerCase().includes(search.toLowerCase()) || u.user_id.includes(search)
  )

  return (
    <div className="space-y-4">
      <input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search by tag, username, or user ID…"
        className="w-full bg-[#111118] border border-[#1e1e2e] rounded-xl px-4 py-3 text-sm text-white focus:border-blue-500 outline-none" />

      <div className="bg-[#111118] border border-[#1e1e2e] rounded-xl overflow-hidden">
        <table className="w-full text-sm">
          <thead>
            <tr className="border-b border-[#1e1e2e]">
              <th className="px-4 py-3 text-left text-xs font-bold text-[#4a4a6a] uppercase tracking-widest">User</th>
              <th className="px-4 py-3 text-left text-xs font-bold text-[#4a4a6a] uppercase tracking-widest">Roles</th>
              <th className="px-4 py-3 text-center text-xs font-bold text-[#4a4a6a] uppercase tracking-widest">Logins</th>
              <th className="px-4 py-3 text-center text-xs font-bold text-[#4a4a6a] uppercase tracking-widest">Status</th>
              <th className="px-4 py-3 text-right text-xs font-bold text-[#4a4a6a] uppercase tracking-widest">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-[#1e1e2e]">
            {filtered.map((u) => (
              <>
                <tr key={u.user_id} className={`hover:bg-[#0d0d15] transition-colors ${u.is_banned ? "opacity-60" : ""}`}>
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-3">
                      <img src={u.avatar ?? "/placeholder-user.jpg"} className="w-8 h-8 rounded-full border border-[#1e1e2e]" alt="" />
                      <div>
                        <div className="font-semibold text-white">{u.discord_tag}</div>
                        <div className="text-[10px] text-[#4a4a6a]">{u.user_id}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-4 py-3">
                    <div className="flex gap-1 flex-wrap">
                      {u.roles_cache.active_roles.length === 0 ? <span className="text-xs text-[#4a4a6a]">No roles</span> : u.roles_cache.active_roles.map((r) => <RoleBadge key={r} role={r} />)}
                    </div>
                  </td>
                  <td className="px-4 py-3 text-center">
                    <div className="text-sm text-white">{u.login_count}</div>
                    <div className="text-[10px] text-[#4a4a6a]">{new Date(u.last_login).toLocaleDateString("th-TH")}</div>
                  </td>
                  <td className="px-4 py-3 text-center">
                    {u.is_banned ? <span className="text-xs font-bold px-2 py-0.5 rounded-full bg-red-900/40 text-red-400">BANNED</span> : <span className="text-xs font-bold px-2 py-0.5 rounded-full bg-green-900/40 text-green-400">Active</span>}
                  </td>
                  <td className="px-4 py-3">
                    <div className="flex items-center justify-end gap-1">
                      <button onClick={() => setExpandedUser(expandedUser === u.user_id ? null : u.user_id)} className="px-2 py-1 text-xs bg-[#1e1e2e] hover:bg-[#2a2a3e] rounded text-[#6b6b8a] hover:text-white">Details</button>
                      <button onClick={() => run(() => adminForceRoleSync(u.user_id), "Role sync forced")} className="px-2 py-1 text-xs bg-[#1e1e2e] hover:bg-[#2a2a3e] rounded text-[#6b6b8a] hover:text-white">Sync</button>
                      {u.is_banned ? (
                        <button onClick={() => run(() => adminUnbanUser(u.user_id), `${u.discord_tag} unbanned`)} className="px-2 py-1 text-xs bg-green-900/30 hover:bg-green-900/50 rounded text-green-400">Unban</button>
                      ) : (
                        <button onClick={() => { setBanReason(""); setBanDialog(u) }} className="px-2 py-1 text-xs bg-red-900/30 hover:bg-red-900/50 rounded text-red-400">Ban</button>
                      )}
                    </div>
                  </td>
                </tr>
                {expandedUser === u.user_id && (
                  <tr key={`${u.user_id}-detail`}>
                    <td colSpan={5} className="px-4 pb-4 bg-[#0a0a0f]">
                      <UserDetailPanel user={u} />
                    </td>
                  </tr>
                )}
              </>
            ))}
          </tbody>
        </table>
      </div>

      {banDialog && (
        <ConfirmDialog
          title={`Ban ${banDialog.discord_tag}?`}
          message="This user will be immediately logged out and blocked from accessing the platform."
          confirmLabel="Confirm Ban"
          danger
          withInput={{ label: "Ban Reason (required)", placeholder: "e.g. Sharing links outside", onValue: (v) => setBanReason(v) }}
          onConfirm={() => {
            if (!banReason.trim()) { notify("Ban reason is required", "err"); return }
            run(() => adminBanUser(banDialog.user_id, banReason.trim()), `${banDialog.discord_tag} banned`)
            setBanDialog(null)
          }}
          onCancel={() => setBanDialog(null)}
        />
      )}
    </div>
  )
}

// ─── User Detail Panel ────────────────────────────────────────────────────────
function UserDetailPanel({ user }: { user: AppUser }) {
  const recentAudit = [...user.audit_log].reverse().slice(0, 10)
  const totalCopies = Object.values(user.link_usage).reduce((sum, g) => sum + Object.values(g).reduce((s, l) => s + l.copy_count, 0), 0)

  return (
    <div className="mt-2 grid md:grid-cols-2 gap-4">
      <div className="bg-[#111118] border border-[#1e1e2e] rounded-xl p-4">
        <div className="text-xs font-bold text-[#4a4a6a] uppercase tracking-widest mb-3">Profile</div>
        <div className="space-y-2 text-xs">
          <div className="flex justify-between"><span className="text-[#4a4a6a]">User ID</span><span className="text-white font-mono">{user.user_id}</span></div>
          <div className="flex justify-between"><span className="text-[#4a4a6a]">Username</span><span className="text-white">{user.username}</span></div>
          <div className="flex justify-between"><span className="text-[#4a4a6a]">First Login</span><span className="text-white">{new Date(user.first_login).toLocaleString("th-TH")}</span></div>
          <div className="flex justify-between"><span className="text-[#4a4a6a]">Last Login</span><span className="text-white">{new Date(user.last_login).toLocaleString("th-TH")}</span></div>
          <div className="flex justify-between"><span className="text-[#4a4a6a]">Total Logins</span><span className="text-white">{user.login_count}</span></div>
          <div className="flex justify-between"><span className="text-[#4a4a6a]">Total Copies</span><span className="text-blue-400 font-bold">{totalCopies}</span></div>
          <div className="flex justify-between"><span className="text-[#4a4a6a]">Favorites</span><span className="text-white">{user.favorites.length}</span></div>
          {user.is_banned && <div className="flex justify-between"><span className="text-[#4a4a6a]">Ban Reason</span><span className="text-red-400">{user.ban_reason}</span></div>}
          <div className="flex justify-between"><span className="text-[#4a4a6a]">Cache Expires</span>
            <span className={new Date(user.roles_cache.cache_expires_at) < new Date() ? "text-red-400" : "text-green-400"}>
              {new Date(user.roles_cache.cache_expires_at).toLocaleTimeString("th-TH")}
            </span>
          </div>
        </div>
      </div>
      <div className="bg-[#111118] border border-[#1e1e2e] rounded-xl p-4">
        <div className="text-xs font-bold text-[#4a4a6a] uppercase tracking-widest mb-3">Recent Audit Log</div>
        <div className="space-y-1.5 max-h-[200px] overflow-y-auto pr-1">
          {recentAudit.length === 0 && <div className="text-xs text-[#4a4a6a]">No activity</div>}
          {recentAudit.map((entry, i) => (
            <div key={i} className="flex items-start justify-between text-[11px]">
              <div>
                <span className="font-mono text-white">{entry.action}</span>
                {entry.gallery_id && <span className="text-[#4a4a6a] ml-1">/ {entry.gallery_id}</span>}
              </div>
              <span className="text-[#4a4a6a] ml-2 shrink-0">{new Date(entry.timestamp).toLocaleString("th-TH", { hour: "2-digit", minute: "2-digit", day: "2-digit", month: "2-digit" })}</span>
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

// ─── Tags Tab ─────────────────────────────────────────────────────────────────
function TagsTab({ tags, run, notify, session }: { tags: Tag[]; run: (fn: () => Promise<{ ok: boolean }>, msg: string) => void; notify: (msg: string, type?: "ok" | "err") => void; session: SessionUser }) {
  const [showCreate, setShowCreate] = useState(false)
  const [form, setForm] = useState({ name: "", display: "", color: "#3b82f6" })
  const [deleteDialog, setDeleteDialog] = useState<Tag | null>(null)

  return (
    <div className="space-y-6">
      <button onClick={() => setShowCreate(!showCreate)} className="px-4 py-2 bg-blue-600 hover:bg-blue-700 rounded-lg text-sm font-semibold transition-colors">
        {showCreate ? "✕ Cancel" : "+ New Tag"}
      </button>

      {showCreate && (
        <div className="bg-[#111118] border border-[#1e1e2e] rounded-xl p-6 space-y-4">
          <div className="text-sm font-bold text-white">Create New Tag</div>
          <div className="grid grid-cols-3 gap-4">
            <div>
              <label className="text-xs text-[#4a4a6a] block mb-1">Name (slug)</label>
              <input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value.toLowerCase().replace(/\s+/g, "_") })} className="w-full bg-[#0d0d15] border border-[#1e1e2e] rounded-lg px-3 py-2 text-sm text-white focus:border-blue-500 outline-none" placeholder="onlyfans" />
            </div>
            <div>
              <label className="text-xs text-[#4a4a6a] block mb-1">Display Name</label>
              <input value={form.display} onChange={(e) => setForm({ ...form, display: e.target.value })} className="w-full bg-[#0d0d15] border border-[#1e1e2e] rounded-lg px-3 py-2 text-sm text-white focus:border-blue-500 outline-none" placeholder="OnlyFans" />
            </div>
            <div>
              <label className="text-xs text-[#4a4a6a] block mb-1">Color</label>
              <div className="flex gap-2">
                <input type="color" value={form.color} onChange={(e) => setForm({ ...form, color: e.target.value })} className="w-10 h-9 rounded bg-transparent border-none cursor-pointer" />
                <input value={form.color} onChange={(e) => setForm({ ...form, color: e.target.value })} className="flex-1 bg-[#0d0d15] border border-[#1e1e2e] rounded-lg px-3 py-2 text-sm text-white focus:border-blue-500 outline-none font-mono" />
              </div>
            </div>
          </div>
          <div className="flex gap-3 items-center">
            <button onClick={() => { if (!form.name || !form.display) { notify("Name & display required", "err"); return } run(() => adminCreateTag({ ...form }), `Tag "${form.display}" created`); setShowCreate(false); setForm({ name: "", display: "", color: "#3b82f6" }) }} className="px-4 py-2 bg-blue-600 hover:bg-blue-700 rounded-lg text-sm font-semibold transition-colors">Create</button>
            <button onClick={() => setShowCreate(false)} className="px-4 py-2 text-[#6b6b8a] hover:text-white text-sm transition-colors">Cancel</button>
            {form.name && form.display && (
              <div style={{ backgroundColor: form.color + "22", color: form.color, borderColor: form.color + "44" }} className="px-2 py-1 rounded border text-xs font-bold">Preview: {form.display}</div>
            )}
          </div>
        </div>
      )}

      <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-4">
        {tags.map((t) => (
          <div key={t.id} className="bg-[#111118] border border-[#1e1e2e] rounded-xl p-4 hover:border-[#2a2a3e] transition-colors">
            <div className="flex items-center justify-between mb-3">
              <div style={{ backgroundColor: t.color + "22", color: t.color, borderColor: t.color + "44" }} className="px-2 py-1 rounded border text-sm font-bold">{t.display}</div>
              <span className={`text-xs font-bold px-2 py-0.5 rounded-full ${t.is_active ? "bg-green-900/40 text-green-400" : "bg-[#1e1e2e] text-[#4a4a6a]"}`}>{t.is_active ? "Active" : "Inactive"}</span>
            </div>
            <div className="text-[10px] text-[#4a4a6a] space-y-0.5 mb-3">
              <div>ID: <span className="font-mono text-white">{t.id}</span></div>
              <div>Slug: <span className="font-mono text-white">{t.name}</span></div>
              <div>Color: <span className="font-mono" style={{ color: t.color }}>{t.color}</span></div>
              <div>Galleries: <span className="text-white">{t.gallery_count}</span></div>
            </div>
            <div className="flex gap-2">
              <button onClick={() => run(() => adminUpdateTag(t.id, { is_active: !t.is_active }), t.is_active ? "Tag disabled" : "Tag enabled")} className="flex-1 px-2 py-1.5 text-xs bg-[#1e1e2e] hover:bg-[#2a2a3e] rounded text-[#6b6b8a] hover:text-white font-semibold transition-colors">{t.is_active ? "Disable" : "Enable"}</button>
              <button onClick={() => setDeleteDialog(t)} className="px-3 py-1.5 text-xs bg-red-900/30 hover:bg-red-900/50 rounded text-red-400 font-semibold transition-colors">Delete</button>
            </div>
          </div>
        ))}
      </div>

      {deleteDialog && (
        <ConfirmDialog
          title={`Delete tag "${deleteDialog.display}"?`}
          message={`This tag will be removed from all ${deleteDialog.gallery_count} galleries using it.`}
          confirmLabel="Delete Tag"
          danger
          onConfirm={() => { run(() => adminDeleteTag(deleteDialog.id), "Tag deleted"); setDeleteDialog(null) }}
          onCancel={() => setDeleteDialog(null)}
        />
      )}
    </div>
  )
}

// ─── Announcement Tab ─────────────────────────────────────────────────────────
function AnnouncementTab({ current, run }: { current: AnnouncementBanner | null; run: (fn: () => Promise<{ ok: boolean }>, msg: string) => void }) {
  const [message, setMessage] = useState(current?.message ?? "")
  const [type, setType] = useState<"info" | "warning" | "success">(current?.type ?? "info")

  const typeColors = {
    info: "text-blue-400 bg-blue-900/30 border-blue-700",
    warning: "text-yellow-400 bg-yellow-900/30 border-yellow-700",
    success: "text-green-400 bg-green-900/30 border-green-700",
  }

  return (
    <div className="max-w-2xl space-y-6">
      <div className="bg-[#111118] border border-[#1e1e2e] rounded-xl p-6 space-y-4">
        <div className="text-sm font-bold text-white">Announcement Banner</div>
        <div className="text-xs text-[#4a4a6a]">Banner will be shown to all users on the main page. Leave blank to clear.</div>
        {current && (
          <div className={`flex items-start gap-3 px-4 py-3 rounded-xl border text-sm ${typeColors[current.type]}`}>
            <span>{current.type === "info" ? "ℹ️" : current.type === "warning" ? "⚠️" : "✅"}</span>
            <div>
              <div className="font-semibold">{current.message}</div>
              <div className="text-[10px] opacity-70 mt-1">Active since {new Date(current.created_at).toLocaleString("th-TH")}</div>
            </div>
          </div>
        )}
        <div>
          <label className="text-xs text-[#4a4a6a] block mb-2">Type</label>
          <div className="flex gap-2">
            {(["info", "warning", "success"] as const).map((t) => (
              <button key={t} onClick={() => setType(t)} className={`px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all ${type === t ? typeColors[t] : "border-[#1e1e2e] text-[#4a4a6a]"}`}>
                {t === "info" ? "ℹ️ Info" : t === "warning" ? "⚠️ Warning" : "✅ Success"}
              </button>
            ))}
          </div>
        </div>
        <div>
          <label className="text-xs text-[#4a4a6a] block mb-2">Message</label>
          <textarea value={message} onChange={(e) => setMessage(e.target.value)} rows={3} className="w-full bg-[#0d0d15] border border-[#1e1e2e] rounded-xl px-4 py-3 text-sm text-white focus:border-blue-500 outline-none resize-none" placeholder="Type announcement here… (empty = clear)" />
        </div>
        {message && (
          <div className={`flex items-start gap-3 px-4 py-3 rounded-xl border text-sm ${typeColors[type]}`}>
            <span>{type === "info" ? "ℹ️" : type === "warning" ? "⚠️" : "✅"}</span>
            <span>{message}</span>
          </div>
        )}
        <div className="flex gap-3">
          <button onClick={() => run(() => adminSetAnnouncement(message, message ? type : null), message ? "Announcement set" : "Announcement cleared")} className="px-4 py-2 bg-blue-600 hover:bg-blue-700 rounded-lg text-sm font-semibold transition-colors">
            {message ? "Set Announcement" : "Clear Announcement"}
          </button>
          {current && (
            <button onClick={() => { setMessage(""); run(() => adminSetAnnouncement("", null), "Announcement cleared") }} className="px-4 py-2 border border-red-700 text-red-400 hover:bg-red-900/20 rounded-lg text-sm font-semibold transition-colors">Clear Now</button>
          )}
        </div>
      </div>
    </div>
  )
}

// ─── Backup Tab ───────────────────────────────────────────────────────────────
function BackupTab({ notify, galleries, run }: { notify: (msg: string, type?: "ok" | "err") => void; galleries: Gallery[]; run: (fn: () => Promise<{ ok: boolean }>, msg: string) => void }) {
  const [isExporting, setIsExporting] = useState(false)
  const totalLinks = galleries.reduce((a, g) => a + g.links.length, 0)
  const deadLinks = galleries.flatMap((g) => g.links).filter((l) => !l.is_active).length
  const healthPct = totalLinks > 0 ? Math.round(((totalLinks - deadLinks) / totalLinks) * 100) : 100

  async function handleExport() {
    setIsExporting(true)
    try {
      const result = await adminCreateBackup()
      const blob = new Blob([result.data], { type: "application/json" })
      const url = URL.createObjectURL(blob)
      const a = document.createElement("a")
      a.href = url
      a.download = `solara-backup-${new Date().toISOString().slice(0, 10)}.json`
      a.click()
      URL.revokeObjectURL(url)
      notify("Backup downloaded!")
    } catch (e) {
      notify((e as Error).message, "err")
    } finally {
      setIsExporting(false)
    }
  }

  return (
    <div className="max-w-2xl space-y-6">
      <div className="bg-[#111118] border border-[#1e1e2e] rounded-xl p-6">
        <div className="text-sm font-bold text-white mb-4">🔗 Link Health Monitor</div>
        <div className="grid grid-cols-3 gap-4 mb-4">
          <StatCard label="Total Links" value={totalLinks} />
          <StatCard label="Active" value={totalLinks - deadLinks} accent="text-green-400" />
          <StatCard label="Dead / Off" value={deadLinks} accent={deadLinks > 0 ? "text-red-400" : "text-white"} />
        </div>
        <div className="mb-4">
          <div className="flex justify-between text-xs text-[#4a4a6a] mb-1">
            <span>Health Score</span>
            <span className={healthPct === 100 ? "text-green-400" : healthPct > 70 ? "text-yellow-400" : "text-red-400"}>{healthPct}%</span>
          </div>
          <div className="h-1.5 bg-[#1e1e2e] rounded-full overflow-hidden">
            <div className={`h-full rounded-full transition-all ${healthPct === 100 ? "bg-green-500" : healthPct > 70 ? "bg-yellow-500" : "bg-red-500"}`} style={{ width: `${healthPct}%` }} />
          </div>
        </div>
        <div className="space-y-2">
          {galleries.flatMap((g) => g.links.filter((l) => !l.is_active).map((l) => (
            <div key={l.id} className="flex items-center justify-between px-3 py-2 bg-red-900/10 border border-red-900/30 rounded-lg">
              <div>
                <div className="text-xs font-semibold text-red-400">{l.label}</div>
                <div className="text-[10px] text-[#4a4a6a]">{g.title} · {l.null_reason ?? "disabled"}</div>
              </div>
              <div className="text-[10px] text-[#4a4a6a]">{l.total_copies} copies</div>
            </div>
          )))}
          {deadLinks === 0 && <div className="text-xs text-green-400">✓ All links are active</div>}
        </div>
      </div>

      <div className="bg-[#111118] border border-[#1e1e2e] rounded-xl p-6 space-y-4">
        <div className="text-sm font-bold text-white">💾 Database Backup</div>
        <div className="text-xs text-[#4a4a6a]">Downloads a full JSON snapshot of users.json, gallery.json, and tag.json. Store it somewhere safe — this is your only recovery point if the server crashes.</div>
        <div className="p-3 bg-yellow-900/20 border border-yellow-700/50 rounded-lg text-xs text-yellow-400">⚠️ This file contains all user data including audit logs. Handle with care.</div>
        <button onClick={handleExport} disabled={isExporting} className="px-5 py-2.5 bg-blue-600 hover:bg-blue-700 disabled:opacity-50 rounded-lg text-sm font-semibold flex items-center gap-2 transition-colors">
          {isExporting ? <><div className="w-3.5 h-3.5 border-2 border-white border-t-transparent rounded-full animate-spin" /> Preparing…</> : <>⬇ Download Backup</>}
        </button>
      </div>
    </div>
  )
}

// ─── Edit Gallery Modal ────────────────────────────────────────────────────────
function EditGalleryModal({ gallery, tags, onClose, run, notify }: { gallery: Gallery; tags: Tag[]; onClose: () => void; run: (fn: () => Promise<{ ok: boolean }>, msg: string) => void; notify: (msg: string, type?: "ok" | "err") => void }) {
  const [form, setForm] = useState({
    title: gallery.title,
    description: gallery.description,
    thumbnail: gallery.thumbnail,
    tags: gallery.tags,
    minRoleName: gallery.access.min_role_name,
    minLevel: gallery.access.min_hierarchy_level,
    is_pinned: gallery.is_pinned,
    is_active: gallery.is_active,
  })
  const [thumbError, setThumbError] = useState(false)

  useEffect(() => {
    const handler = (e: KeyboardEvent) => { if (e.key === "Escape") onClose() }
    window.addEventListener("keydown", handler)
    return () => window.removeEventListener("keydown", handler)
  }, [onClose])

  function handleSave() {
    if (!form.title.trim()) { notify("Title is required", "err"); return }
    run(() => adminUpdateGallery(gallery.id, { title: form.title, description: form.description, thumbnail: form.thumbnail, tags: form.tags, minRoleName: form.minRoleName, minLevel: form.minLevel, is_pinned: form.is_pinned, is_active: form.is_active }), `"${form.title}" updated`)
    onClose()
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm" onClick={onClose}>
      <div className="bg-[#111118] border border-[#1e1e2e] rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between px-6 py-4 border-b border-[#1e1e2e] sticky top-0 bg-[#111118] z-10">
          <div>
            <div className="text-sm font-bold text-white">✏️ Edit Gallery</div>
            <div className="text-[10px] text-[#4a4a6a] font-mono mt-0.5">{gallery.id}</div>
          </div>
          <button onClick={onClose} className="text-[#4a4a6a] hover:text-white text-xl leading-none transition-colors w-8 h-8 flex items-center justify-center rounded-lg hover:bg-[#1e1e2e]">×</button>
        </div>

        <div className="p-6 space-y-5">
          {/* Thumbnail preview at top */}
          {form.thumbnail && !thumbError && (
            <div className="relative h-32 rounded-xl overflow-hidden border border-[#1e1e2e]">
              <img src={form.thumbnail} alt="" className="w-full h-full object-cover"
                onError={() => setThumbError(true)} />
              <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent flex items-end px-3 pb-2">
                <span className="text-[10px] text-white/60">Thumbnail preview</span>
              </div>
            </div>
          )}

          <div>
            <label className="text-xs font-semibold text-[#4a4a6a] uppercase tracking-widest block mb-2">Title *</label>
            <input value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })}
              className="w-full bg-[#0d0d15] border border-[#1e1e2e] rounded-xl px-4 py-2.5 text-sm text-white focus:border-blue-500 outline-none transition-colors" />
          </div>

          <div>
            <label className="text-xs font-semibold text-[#4a4a6a] uppercase tracking-widest block mb-2">Description</label>
            <textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })}
              rows={3} className="w-full bg-[#0d0d15] border border-[#1e1e2e] rounded-xl px-4 py-2.5 text-sm text-white focus:border-blue-500 outline-none resize-none transition-colors" />
          </div>

          <div>
            <label className="text-xs font-semibold text-[#4a4a6a] uppercase tracking-widest block mb-2">Thumbnail URL</label>
            <input
              value={form.thumbnail}
              onChange={(e) => { setForm({ ...form, thumbnail: e.target.value }); setThumbError(false) }}
              className="w-full bg-[#0d0d15] border border-[#1e1e2e] rounded-xl px-4 py-2.5 text-sm text-white focus:border-blue-500 outline-none transition-colors"
              placeholder="/collection-thumb.jpg or https://…"
            />
          </div>

          <div>
            <label className="text-xs font-semibold text-[#4a4a6a] uppercase tracking-widest block mb-2">Min Role Required</label>
            <div className="flex gap-2 flex-wrap">
              {ROLES.map((r) => (
                <button key={r} onClick={() => setForm({ ...form, minRoleName: r, minLevel: ROLE_LEVELS[r] })}
                  style={{
                    borderColor: form.minRoleName === r ? ROLE_COLORS[r] : "#1e1e2e",
                    color: form.minRoleName === r ? ROLE_COLORS[r] : "#6b6b8a",
                    backgroundColor: form.minRoleName === r ? ROLE_COLORS[r] + "22" : "transparent",
                  }}
                  className="px-3 py-1.5 rounded-lg border text-xs font-bold transition-all">{r}</button>
              ))}
            </div>
          </div>

          <div>
            <label className="text-xs font-semibold text-[#4a4a6a] uppercase tracking-widest block mb-2">
              Tags <span className="text-[#4a4a6a] normal-case font-normal">({form.tags.length} selected)</span>
            </label>
            <div className="flex gap-2 flex-wrap">
              {tags.filter((t) => t.is_active).map((t) => {
                const isSelected = form.tags.includes(t.id)
                return (
                  <button key={t.id}
                    onClick={() => { const s = new Set(form.tags); isSelected ? s.delete(t.id) : s.add(t.id); setForm({ ...form, tags: [...s] }) }}
                    style={{
                      borderColor: isSelected ? t.color : "#1e1e2e",
                      color: isSelected ? t.color : "#6b6b8a",
                      backgroundColor: isSelected ? t.color + "22" : "transparent",
                    }}
                    className="px-3 py-1.5 rounded-lg border text-xs font-semibold transition-all">{t.display}</button>
                )
              })}
              {tags.filter((t) => t.is_active).length === 0 && <span className="text-xs text-[#4a4a6a]">No active tags</span>}
            </div>
          </div>

          <div className="flex gap-6">
            {[{ key: "is_pinned", label: "📌 Pinned", color: "bg-blue-600" }, { key: "is_active", label: "Active", color: "bg-green-600" }].map(({ key, label, color }) => (
              <label key={key} className="flex items-center gap-2.5 cursor-pointer">
                <div onClick={() => setForm({ ...form, [key]: !form[key as keyof typeof form] })} className={`w-9 h-5 rounded-full transition-colors relative ${form[key as keyof typeof form] ? color : "bg-[#1e1e2e]"}`}>
                  <div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full shadow transition-transform ${form[key as keyof typeof form] ? "translate-x-4" : "translate-x-0.5"}`} />
                </div>
                <span className="text-sm text-white">{label}</span>
              </label>
            ))}
          </div>
        </div>

        <div className="flex items-center justify-between px-6 py-4 border-t border-[#1e1e2e] bg-[#0d0d15] rounded-b-2xl sticky bottom-0">
          <button onClick={onClose} className="px-4 py-2 text-sm text-[#6b6b8a] hover:text-white transition-colors">Cancel</button>
          <button onClick={handleSave} className="px-6 py-2 bg-blue-600 hover:bg-blue-700 rounded-xl text-sm font-semibold transition-colors">Save Changes</button>
        </div>
      </div>
    </div>
  )
}

// ─── Create Gallery Modal ──────────────────────────────────────────────────────
function CreateGalleryModal({ tags, onClose, run, notify }: { tags: Tag[]; onClose: () => void; run: (fn: () => Promise<{ ok: boolean }>, msg: string) => void; notify: (msg: string, type?: "ok" | "err") => void }) {
  const [form, setForm] = useState({
    title: "", description: "", thumbnail: "",
    tags: [] as string[],
    minRoleName: ROLES[0] as typeof ROLES[number],
    minLevel: 1, isPinned: false,
  })
  const [thumbError, setThumbError] = useState(false)

  useEffect(() => {
    const handler = (e: KeyboardEvent) => { if (e.key === "Escape") onClose() }
    window.addEventListener("keydown", handler)
    return () => window.removeEventListener("keydown", handler)
  }, [onClose])

  function handleCreate() {
    if (!form.title.trim()) { notify("Title is required", "err"); return }
    run(() => adminCreateGallery({ title: form.title, description: form.description, thumbnail: form.thumbnail, tags: form.tags, minLevel: form.minLevel, minRoleName: form.minRoleName, isPinned: form.isPinned }), `"${form.title}" created`)
    onClose()
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm" onClick={onClose}>
      <div className="bg-[#111118] border border-[#1e1e2e] rounded-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto shadow-2xl" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between px-6 py-4 border-b border-[#1e1e2e] sticky top-0 bg-[#111118] z-10">
          <div className="text-sm font-bold text-white">✨ Create New Gallery</div>
          <button onClick={onClose} className="text-[#4a4a6a] hover:text-white text-xl leading-none transition-colors w-8 h-8 flex items-center justify-center rounded-lg hover:bg-[#1e1e2e]">×</button>
        </div>

        <div className="p-6 space-y-5">
          {form.thumbnail && !thumbError && (
            <div className="relative h-28 rounded-xl overflow-hidden border border-[#1e1e2e]">
              <img src={form.thumbnail} alt="" className="w-full h-full object-cover"
                onError={() => setThumbError(true)} />
              <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent flex items-end px-3 pb-2">
                <span className="text-[10px] text-white/60">Thumbnail preview</span>
              </div>
            </div>
          )}

          <div>
            <label className="text-xs font-semibold text-[#4a4a6a] uppercase tracking-widest block mb-2">Title *</label>
            <input value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })}
              className="w-full bg-[#0d0d15] border border-[#1e1e2e] rounded-xl px-4 py-2.5 text-sm text-white focus:border-blue-500 outline-none" placeholder="Gallery name…" autoFocus />
          </div>

          <div>
            <label className="text-xs font-semibold text-[#4a4a6a] uppercase tracking-widest block mb-2">Description</label>
            <textarea value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })}
              rows={3} className="w-full bg-[#0d0d15] border border-[#1e1e2e] rounded-xl px-4 py-2.5 text-sm text-white focus:border-blue-500 outline-none resize-none" placeholder="Optional description…" />
          </div>

          <div>
            <label className="text-xs font-semibold text-[#4a4a6a] uppercase tracking-widest block mb-2">Thumbnail URL</label>
            <input
              value={form.thumbnail}
              onChange={(e) => { setForm({ ...form, thumbnail: e.target.value }); setThumbError(false) }}
              className="w-full bg-[#0d0d15] border border-[#1e1e2e] rounded-xl px-4 py-2.5 text-sm text-white focus:border-blue-500 outline-none"
              placeholder="/collection-thumb.jpg or https://…"
            />
          </div>

          <div>
            <label className="text-xs font-semibold text-[#4a4a6a] uppercase tracking-widest block mb-2">Min Role Required</label>
            <div className="flex gap-2 flex-wrap">
              {ROLES.map((r) => (
                <button key={r} onClick={() => setForm({ ...form, minRoleName: r, minLevel: ROLE_LEVELS[r] })}
                  style={{
                    borderColor: form.minRoleName === r ? ROLE_COLORS[r] : "#1e1e2e",
                    color: form.minRoleName === r ? ROLE_COLORS[r] : "#6b6b8a",
                    backgroundColor: form.minRoleName === r ? ROLE_COLORS[r] + "22" : "transparent",
                  }}
                  className="px-3 py-1.5 rounded-lg border text-xs font-bold transition-all">{r}</button>
              ))}
            </div>
          </div>

          <div>
            <label className="text-xs font-semibold text-[#4a4a6a] uppercase tracking-widest block mb-2">Tags</label>
            <div className="flex gap-2 flex-wrap">
              {tags.filter((t) => t.is_active).map((t) => {
                const sel = form.tags.includes(t.id)
                return (
                  <button key={t.id}
                    onClick={() => { const s = new Set(form.tags); sel ? s.delete(t.id) : s.add(t.id); setForm({ ...form, tags: [...s] }) }}
                    style={{
                      borderColor: sel ? t.color : "#1e1e2e",
                      color: sel ? t.color : "#6b6b8a",
                      backgroundColor: sel ? t.color + "22" : "transparent",
                    }}
                    className="px-3 py-1.5 rounded-lg border text-xs font-semibold transition-all">{t.display}</button>
                )
              })}
              {tags.filter((t) => t.is_active).length === 0 && <span className="text-xs text-[#4a4a6a]">No active tags</span>}
            </div>
          </div>

          <label className="flex items-center gap-2.5 cursor-pointer">
            <div onClick={() => setForm({ ...form, isPinned: !form.isPinned })} className={`w-9 h-5 rounded-full transition-colors relative ${form.isPinned ? "bg-blue-600" : "bg-[#1e1e2e]"}`}>
              <div className={`absolute top-0.5 w-4 h-4 bg-white rounded-full shadow transition-transform ${form.isPinned ? "translate-x-4" : "translate-x-0.5"}`} />
            </div>
            <span className="text-sm text-white">📌 Pin this gallery</span>
          </label>
        </div>

        <div className="flex items-center justify-between px-6 py-4 border-t border-[#1e1e2e] bg-[#0d0d15] rounded-b-2xl sticky bottom-0">
          <button onClick={onClose} className="px-4 py-2 text-sm text-[#6b6b8a] hover:text-white transition-colors">Cancel</button>
          <button onClick={handleCreate} className="px-6 py-2 bg-blue-600 hover:bg-blue-700 rounded-xl text-sm font-semibold transition-colors">Create Gallery</button>
        </div>
      </div>
    </div>
  )
}