"use client"

import { useEffect, useRef, useState, useTransition, useCallback } from "react"
import type { AnnouncementNote } from "@/lib/db"
import { adminSaveNote } from "@/app/admin/actions"
import { toast } from "sonner"

interface NoteEditorProps {
  initialNote: AnnouncementNote | null
}

const TOOLBAR_BTNS = [
  { cmd: "bold",          icon: "B",  title: "Bold",         style: "font-bold" },
  { cmd: "italic",        icon: "I",  title: "Italic",       style: "italic" },
  { cmd: "underline",     icon: "U",  title: "Underline",    style: "underline" },
  { cmd: "strikeThrough", icon: "S",  title: "Strikethrough",style: "line-through" },
] as const

const HEADING_OPTIONS = [
  { tag: "H1", label: "หัวข้อใหญ่ (H1)" },
  { tag: "H2", label: "หัวข้อรอง (H2)" },
  { tag: "H3", label: "หัวข้อย่อย (H3)" },
  { tag: "DIV", label: "ข้อความปกติ" },
] as const

const LIST_BTNS = [
  { cmd: "insertUnorderedList", icon: "• —", title: "Bullet list" },
  { cmd: "insertOrderedList",   icon: "1. —", title: "Numbered list" },
] as const

const ALIGN_BTNS = [
  { cmd: "justifyLeft",   icon: "≡L", title: "ชิดซ้าย" },
  { cmd: "justifyCenter", icon: "≡C", title: "กึ่งกลาง" },
  { cmd: "justifyRight",  icon: "≡R", title: "ชิดขวา" },
] as const

const COLOR_PRESETS = [
  "#ffffff", "#f87171", "#fb923c", "#facc15",
  "#4ade80", "#38bdf8", "#a78bfa", "#f472b6",
  "#94a3b8",
]

const SIZE_OPTIONS = [
  { label: "เล็ก",    value: "1" },
  { label: "ปกติ",   value: "3" },
  { label: "ใหญ่",    value: "4" },
  { label: "ใหญ่มาก", value: "5" },
  { label: "ยักษ์",   value: "7" },
]

export function NoteEditor({ initialNote }: NoteEditorProps) {
  const editorRef = useRef<HTMLDivElement>(null)
  const [isPending, startTransition] = useTransition()
  const [charCount, setCharCount] = useState(0)
  const [showImageInput, setShowImageInput] = useState(false)
  const [imageUrl, setImageUrl] = useState("")
  const [showLinkInput, setShowLinkInput] = useState(false)
  const [linkUrl, setLinkUrl] = useState("")
  const [linkText, setLinkText] = useState("")

  // Load initial content
  useEffect(() => {
    if (editorRef.current && initialNote?.content_html) {
      editorRef.current.innerHTML = initialNote.content_html
      setCharCount(editorRef.current.innerText.length)
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  const updateCount = useCallback(() => {
    setCharCount(editorRef.current?.innerText.length ?? 0)
  }, [])

  const exec = useCallback((command: string, value?: string) => {
    editorRef.current?.focus()
    document.execCommand(command, false, value)
    updateCount()
  }, [updateCount])

  const handleHeading = (tag: string) => {
    exec("formatBlock", tag)
  }

  const handleFontSize = (size: string) => {
    exec("fontSize", size)
  }

  const handleColor = (color: string) => {
    exec("foreColor", color)
  }

  const insertHr = () => {
    exec("insertHTML", "<hr style='border:none;border-top:2px solid currentColor;opacity:0.3;margin:1em 0;' />")
  }

  const insertImage = () => {
    if (!imageUrl.trim()) return
    exec("insertHTML", `<img src="${imageUrl.trim()}" alt="note image" style="max-width:100%;border-radius:8px;margin:8px 0;" />`)
    setImageUrl("")
    setShowImageInput(false)
  }

  const insertLink = () => {
    const url = linkUrl.trim()
    const text = linkText.trim() || url
    if (!url) return
    exec("insertHTML", `<a href="${url}" target="_blank" rel="noopener" style="color:inherit;text-decoration:underline;">${text}</a>`)
    setLinkUrl("")
    setLinkText("")
    setShowLinkInput(false)
  }

  const handleSave = () => {
    const html = editorRef.current?.innerHTML ?? ""
    const text = editorRef.current?.innerText ?? ""
    startTransition(async () => {
      try {
        await adminSaveNote(html, text)
        toast.success("บันทึก Note แล้ว")
      } catch {
        toast.error("บันทึกไม่สำเร็จ")
      }
    })
  }

  const handleClear = () => {
    if (!editorRef.current) return
    editorRef.current.innerHTML = ""
    setCharCount(0)
  }

  const btnCls = "px-2 py-1 text-xs rounded hover:bg-[#2a2a3e] text-[#8b8baa] hover:text-white transition-colors border border-transparent hover:border-[#3a3a5e] select-none cursor-pointer"
  const activeBtnCls = "bg-[#2563eb]/20 text-[#60a5fa] border-[#2563eb]/30"

  return (
    <div className="flex flex-col gap-3 h-full">
      {/* ── Toolbar ─────────────────────────────────────────── */}
      <div className="bg-[#0d0d15] border border-[#1e1e2e] rounded-xl p-2 flex flex-wrap items-center gap-1">

        {/* Heading */}
        <select
          onChange={(e) => handleHeading(e.target.value)}
          defaultValue=""
          className="bg-[#111118] border border-[#1e1e2e] text-[#8b8baa] text-xs rounded px-2 py-1 cursor-pointer hover:border-[#2563eb]/50 outline-none"
        >
          <option value="" disabled>หัวข้อ</option>
          {HEADING_OPTIONS.map(o => (
            <option key={o.tag} value={o.tag}>{o.label}</option>
          ))}
        </select>

        {/* Font size */}
        <select
          onChange={(e) => handleFontSize(e.target.value)}
          defaultValue=""
          className="bg-[#111118] border border-[#1e1e2e] text-[#8b8baa] text-xs rounded px-2 py-1 cursor-pointer hover:border-[#2563eb]/50 outline-none"
        >
          <option value="" disabled>ขนาด</option>
          {SIZE_OPTIONS.map(o => (
            <option key={o.value} value={o.value}>{o.label}</option>
          ))}
        </select>

        <div className="w-px h-5 bg-[#1e1e2e] mx-0.5" />

        {/* Bold / Italic / etc */}
        {TOOLBAR_BTNS.map(b => (
          <button key={b.cmd} type="button" title={b.title} onClick={() => exec(b.cmd)} className={`${btnCls} ${b.style}`}>
            {b.icon}
          </button>
        ))}

        <div className="w-px h-5 bg-[#1e1e2e] mx-0.5" />

        {/* Lists */}
        {LIST_BTNS.map(b => (
          <button key={b.cmd} type="button" title={b.title} onClick={() => exec(b.cmd)} className={btnCls}>
            {b.icon}
          </button>
        ))}

        <div className="w-px h-5 bg-[#1e1e2e] mx-0.5" />

        {/* Alignment */}
        {ALIGN_BTNS.map(b => (
          <button key={b.cmd} type="button" title={b.title} onClick={() => exec(b.cmd)} className={btnCls}>
            {b.icon}
          </button>
        ))}

        <div className="w-px h-5 bg-[#1e1e2e] mx-0.5" />

        {/* Color palette */}
        <div className="flex items-center gap-0.5">
          {COLOR_PRESETS.map(c => (
            <button
              key={c}
              type="button"
              title={`สี ${c}`}
              onClick={() => handleColor(c)}
              style={{ backgroundColor: c }}
              className="size-4 rounded-sm border border-white/10 hover:scale-110 transition-transform cursor-pointer"
            />
          ))}
        </div>

        <div className="w-px h-5 bg-[#1e1e2e] mx-0.5" />

        {/* HR divider */}
        <button type="button" title="เส้นคั่น" onClick={insertHr} className={btnCls}>
          ─
        </button>

        {/* Image insert */}
        <button
          type="button"
          title="แทรกรูปภาพ"
          onClick={() => { setShowImageInput(v => !v); setShowLinkInput(false) }}
          className={`${btnCls} ${showImageInput ? activeBtnCls : ""}`}
        >
          🖼
        </button>

        {/* Link insert */}
        <button
          type="button"
          title="แทรกลิงก์"
          onClick={() => { setShowLinkInput(v => !v); setShowImageInput(false) }}
          className={`${btnCls} ${showLinkInput ? activeBtnCls : ""}`}
        >
          🔗
        </button>

        <div className="w-px h-5 bg-[#1e1e2e] mx-0.5" />

        {/* Undo / Redo */}
        <button type="button" title="ย้อนกลับ" onClick={() => exec("undo")} className={btnCls}>↩</button>
        <button type="button" title="ทำซ้ำ" onClick={() => exec("redo")} className={btnCls}>↪</button>
      </div>

      {/* Inline image URL input */}
      {showImageInput && (
        <div className="flex gap-2 bg-[#0d0d15] border border-[#1e1e2e] rounded-xl p-3">
          <input
            type="url"
            placeholder="URL รูปภาพ (https://...)"
            value={imageUrl}
            onChange={e => setImageUrl(e.target.value)}
            onKeyDown={e => e.key === "Enter" && insertImage()}
            className="flex-1 bg-[#111118] border border-[#1e1e2e] rounded-lg px-3 py-1.5 text-sm text-white outline-none focus:border-[#2563eb]/60"
          />
          <button type="button" onClick={insertImage} className="px-4 py-1.5 bg-blue-600 hover:bg-blue-700 text-white text-sm rounded-lg font-medium transition-colors">
            แทรก
          </button>
          <button type="button" onClick={() => setShowImageInput(false)} className="px-3 py-1.5 text-[#6b6b8a] hover:text-white text-sm rounded-lg transition-colors">
            ✕
          </button>
        </div>
      )}

      {/* Inline link input */}
      {showLinkInput && (
        <div className="flex gap-2 bg-[#0d0d15] border border-[#1e1e2e] rounded-xl p-3 flex-wrap">
          <input
            type="text"
            placeholder="ข้อความลิงก์"
            value={linkText}
            onChange={e => setLinkText(e.target.value)}
            className="flex-1 min-w-[140px] bg-[#111118] border border-[#1e1e2e] rounded-lg px-3 py-1.5 text-sm text-white outline-none focus:border-[#2563eb]/60"
          />
          <input
            type="url"
            placeholder="URL (https://...)"
            value={linkUrl}
            onChange={e => setLinkUrl(e.target.value)}
            onKeyDown={e => e.key === "Enter" && insertLink()}
            className="flex-1 min-w-[200px] bg-[#111118] border border-[#1e1e2e] rounded-lg px-3 py-1.5 text-sm text-white outline-none focus:border-[#2563eb]/60"
          />
          <button type="button" onClick={insertLink} className="px-4 py-1.5 bg-blue-600 hover:bg-blue-700 text-white text-sm rounded-lg font-medium transition-colors">
            แทรก
          </button>
          <button type="button" onClick={() => setShowLinkInput(false)} className="px-3 py-1.5 text-[#6b6b8a] hover:text-white text-sm rounded-lg transition-colors">
            ✕
          </button>
        </div>
      )}

      {/* ── Editor canvas ───────────────────────────────────── */}
      <div
        ref={editorRef}
        contentEditable
        suppressContentEditableWarning
        onInput={updateCount}
        spellCheck={false}
        className="flex-1 min-h-[420px] bg-[#0d0d15] border border-[#1e1e2e] rounded-xl p-5 text-white outline-none focus:border-[#2563eb]/40 overflow-y-auto resize-none leading-relaxed text-sm note-editor-canvas"
        style={{ whiteSpace: "pre-wrap" }}
        data-placeholder="เขียนประกาศที่นี่..."
      />

      {/* ── Footer ──────────────────────────────────────────── */}
      <div className="flex items-center justify-between gap-3">
        <span className="text-xs text-[#4a4a6a]">{charCount.toLocaleString()} ตัวอักษร</span>
        <div className="flex gap-2">
          <button
            type="button"
            onClick={handleClear}
            className="px-4 py-2 text-sm text-[#6b6b8a] hover:text-red-400 border border-[#1e1e2e] hover:border-red-500/30 rounded-xl transition-colors"
          >
            ล้างทั้งหมด
          </button>
          <button
            type="button"
            onClick={handleSave}
            disabled={isPending}
            className="px-6 py-2 text-sm font-semibold bg-blue-600 hover:bg-blue-700 disabled:opacity-50 text-white rounded-xl transition-colors"
          >
            {isPending ? "กำลังบันทึก..." : "บันทึก Note"}
          </button>
        </div>
      </div>

      <style>{`
        .note-editor-canvas:empty:before {
          content: attr(data-placeholder);
          color: #4a4a6a;
          pointer-events: none;
        }
        .note-editor-canvas h1 { font-size: 2em; font-weight: 800; margin: 0.4em 0; }
        .note-editor-canvas h2 { font-size: 1.5em; font-weight: 700; margin: 0.4em 0; }
        .note-editor-canvas h3 { font-size: 1.2em; font-weight: 600; margin: 0.4em 0; }
        .note-editor-canvas ul { list-style: disc; padding-left: 1.5em; }
        .note-editor-canvas ol { list-style: decimal; padding-left: 1.5em; }
        .note-editor-canvas a { text-decoration: underline; }
        .note-editor-canvas img { max-width: 100%; border-radius: 8px; }
        .note-editor-canvas hr { border: none; border-top: 2px solid rgba(255,255,255,0.15); margin: 1em 0; }
      `}</style>
    </div>
  )
}
